])
),
guia_johto AS (
    SELECT array_agg(titulo ORDER BY ordem) AS caps,
           jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough
    FROM capitulos_johto
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough
FROM public.pokemon AS jogo
CROSS JOIN guia_johto AS guia
WHERE jogo.slug IN ('pokemon-gold', 'pokemon-silver')
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Campanha de Pokémon Crystal, com os eventos próprios dessa versão.
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT alvo.slug, origem.caps, jsonb_set(jsonb_set(jsonb_set(jsonb_set(origem.walkthrough, ARRAY['New Bark Town'], jsonb_build_array('O Professor Carvalho apresenta o mundo Pokémon e pergunta seu nome, depois você escolhe seu personagem e começa a jornada em New Bark Town.', 'Fale com sua mãe para receber a Pokégear, depois vá ao laboratório do Professor Elm e escolha entre Chikorita, Cyndaquil e Totodile.', 'Elm pedirá que você visite Mr. Pokémon, então receba uma Potion do assistente e saia de New Bark pelo oeste, seguindo pela Route 29 até Cherrygrove City.'), true), ARRAY['Ecruteak City'], jsonb_build_array('Em Ecruteak City, entre na Burned Tower ao noroeste, conheça Eusine e enfrente seu rival, depois desça até encontrar Raikou, Entei e Suicune, que fugirão da torre.', 'Na casa de dança ao norte do Pokémon Center, derrote as cinco Kimono Girls e fale com o homem presente para receber HM03 Surf.', 'Entre no ginásio e atravesse o caminho invisível até Morty, líder especialista no tipo Fantasma, depois vença a batalha para receber a Fog Badge e poder usar Surf fora das batalhas.', 'Saia de Ecruteak pelo oeste e atravesse as Routes 38 e 39 até Olivine City.'), true), ARRAY['Cianwood City'], jsonb_build_array('Em Olivine City, suba o farol e fale com Jasmine, que está cuidando do Ampharos doente, depois receba HM04 Strength do marinheiro em uma casa ao sul da cidade.', 'Use Surf a partir da praia de Olivine e atravesse as Routes 40 e 41 até Cianwood City, enfrentando os treinadores pelo caminho.', 'Ao norte da cidade, encontre Suicune e enfrente Eusine, depois vá à farmácia ao sul de Cianwood e receba a SecretPotion para Ampharos.', 'Entre no ginásio e derrote Chuck, líder especialista no tipo Lutador, para receber a Storm Badge, depois fale com a mulher do lado de fora para ganhar HM02 Fly e volte a Olivine.'), true), ARRAY['Blackthorn City'], jsonb_build_array('Atravesse a Route 44 e entre no Ice Path, onde você deve pegar HM07 Waterfall e usar Strength para empurrar as pedras nos buracos antes de continuar até Blackthorn City.', 'No ginásio, use Strength para abrir caminho e derrote Clair, líder especialista no tipo Dragão, que pedirá uma prova antes de entregar a insígnia.', 'Use Surf atrás do ginásio para entrar na Dragon’s Den, atravesse o redemoinho com Whirlpool e entre no templo para responder às perguntas do ancião e receber de Clair a Rising Badge.', 'Depois da ligação de Elm, volte ao laboratório em New Bark para receber a Master Ball, então use Surf a leste da cidade e atravesse as Tohjo Falls, usando Waterfall nas cachoeiras.', 'Continue pelas Routes 27 e 26 até a entrada da Victory Road, apresente suas oito insígnias aos guardas e atravesse a caverna, enfrentando seu rival perto da saída para chegar ao Indigo Plateau.'), true)
FROM public.detonados AS origem
JOIN public.pokemon AS alvo ON alvo.slug = 'pokemon-crystal'
WHERE origem.slug = 'pokemon-gold'
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Os remakes compartilham a estrutura, com mudanças próprias de sua jornada.
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT alvo.slug, origem.caps, jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(origem.walkthrough, ARRAY['New Bark Town'], jsonb_build_array('O Professor Carvalho apresenta o mundo Pokémon, pede que você escolha seu personagem e pergunta seu nome antes do início da jornada em New Bark Town.', 'Vá ao laboratório do Professor Elm e escolha entre Chikorita, Cyndaquil e Totodile, depois receba Potions do assistente ao sair.', 'Fale com sua mãe para receber a Pokégear e saia de New Bark pelo oeste, seguindo pela Route 29 até Cherrygrove City para procurar Mr. Pokémon.'), true), ARRAY['Cherrygrove City'], jsonb_build_array('Acompanhe o morador que apresenta Cherrygrove e receba os Running Shoes, depois siga pela saída norte da cidade para receber o mapa da Pokégear e continue pela Route 30 até a casa de Mr. Pokémon.', 'Receba o Mystery Egg de Mr. Pokémon e a Pokédex do Professor Carvalho, depois atenda à ligação de Elm e volte em direção a New Bark Town.', 'Ao sair de Cherrygrove, enfrente o garoto que roubou um dos Pokémon do laboratório e volte a New Bark, onde você contará o nome do seu rival e entregará o ovo a Elm.', 'Ao sair de New Bark, acompanhe a demonstração de captura de Ethan ou Lyra e receba Poké Balls, depois volte a Cherrygrove e siga pelas Routes 30 e 31 até Violet City.'), true), ARRAY['Violet City'], jsonb_build_array('Em Violet City, entre na Sprout Tower ao norte e suba enfrentando os treinadores até vencer o sábio no último andar, que entregará TM70 Flash.', 'Vá ao ginásio e derrote Falkner, líder especialista no tipo Voador, para conquistar a Zephyr Badge, depois encontre o assistente de Elm no Poké Mart para receber o ovo, deixando um espaço livre na equipe.', 'Saia de Violet pelo sul, atravesse a Route 32 e entre na Union Cave, depois continue pela Route 33 até Azalea Town.'), true), ARRAY['Azalea Town'], jsonb_build_array('Em Azalea Town, fale com Kurt na casa ao noroeste para descobrir o que está acontecendo com os Slowpoke, depois entre no Slowpoke Well e derrote os membros da Team Rocket.', 'Com o poço livre, entre no ginásio e vença Bugsy, líder especialista no tipo Inseto, para receber a Hive Badge.', 'Ao sair pela passagem a oeste da cidade, enfrente seu rival e entre na Ilex Forest, onde você deve conduzir os dois Farfetch’d perdidos de volta ao lenhador para receber HM01 Cut.', 'Ensine Cut a um Pokémon, corte a árvore que bloqueia a floresta e siga pela Route 34 até Goldenrod City.'), true), ARRAY['Goldenrod City'], jsonb_build_array('Em Goldenrod City, entre na Radio Tower e responda ao questionário no balcão para receber o Radio Card e encontrar Whitney, que voltará ao ginásio.', 'Vá ao ginásio e derrote Whitney, líder especialista no tipo Normal, depois fale com uma das treinadoras e converse novamente com ela para receber a Plain Badge.', 'Na floricultura ao lado do ginásio, receba a Squirtbottle e saia pelo norte, atravessando a Route 35 e o National Park até encontrar a árvore que bloqueia a Route 36.', 'Use a Squirtbottle na árvore para enfrentar Sudowoodo e, após capturá-lo ou vencê-lo, siga pela Route 37 até Ecruteak City.'), true), ARRAY['Ecruteak City'], jsonb_build_array('Em Ecruteak City, entre no Dance Theater ao norte do Pokémon Center e derrote o membro da Team Rocket que incomoda uma Kimono Girl, depois fale com o homem presente para receber HM03 Surf.', 'Entre na Burned Tower ao noroeste, enfrente seu rival e desça até encontrar Raikou, Entei e Suicune, que fugirão da torre.', 'Entre no ginásio e atravesse o caminho até Morty, líder especialista no tipo Fantasma, depois vença a batalha para receber a Fog Badge e poder usar Surf fora das batalhas.', 'Saia de Ecruteak pelo leste e fale com o homem perto do Mt. Mortar para receber HM04 Strength, depois volte à cidade e siga pelo oeste através das Routes 38 e 39 até Olivine City.'), true), ARRAY['Cianwood City'], jsonb_build_array('Em Olivine City, suba o farol e fale com Jasmine, que está cuidando do Ampharos doente e precisa de um remédio de Cianwood.', 'Use Surf a partir da praia de Olivine e atravesse as Routes 40 e 41 até Cianwood City, enfrentando os treinadores pelo caminho.', 'Na farmácia ao lado do Pokémon Center, fale com o atendente para receber a SecretPotion necessária para Ampharos.', 'No ginásio, desligue a cachoeira e derrote Chuck, líder especialista no tipo Lutador, para receber a Storm Badge, depois fale com a mulher do lado de fora para ganhar HM02 Fly e volte a Olivine.'), true), ARRAY['Mahogany Town'], jsonb_build_array('Siga ao norte de Mahogany pela Route 43 até o Lake of Rage, use Surf para alcançar o Gyarados vermelho e capture-o ou derrote-o, depois fale com Lance na margem do lago.', 'Volte a Mahogany e encontre Lance na loja, onde ele revelará a entrada do esconderijo da Team Rocket, então desça e enfrente os membros da equipe.', 'No esconderijo, obtenha as duas senhas com os membros da Team Rocket, vença o executivo e fale com o Murkrow para descobrir a senha que abre a sala do gerador.', 'Entre na sala, ajude Lance a derrotar os Electrode e receba HM05 Whirlpool, depois saia e derrote Pryce, líder especialista no tipo Gelo, para conquistar a Glacier Badge.', 'Após receber a ligação de Elm, volte a Goldenrod City, entre na passagem subterrânea e obtenha o uniforme da Team Rocket para acessar as escadas da Radio Tower.', 'Suba a Radio Tower, derrote o impostor e receba a Basement Key, depois use a chave na passagem subterrânea, enfrente seu rival e acione os interruptores para alcançar o diretor e receber a Card Key.', 'Retorne à Radio Tower, use a Card Key na passagem bloqueada e derrote os membros restantes da Team Rocket, depois volte a Mahogany e saia pelo leste em direção à Route 44.'), true), ARRAY['Blackthorn City'], jsonb_build_array('Atravesse a Route 44 e entre no Ice Path, onde você deve pegar HM07 Waterfall e usar Strength para empurrar as pedras nos buracos antes de continuar até Blackthorn City.', 'No ginásio, abra caminho e derrote Clair, líder especialista no tipo Dragão, que pedirá uma prova antes de entregar a insígnia.', 'Use Surf atrás do ginásio para entrar na Dragon’s Den, atravesse o redemoinho com Whirlpool e fale com o ancião no templo para responder às perguntas e receber de Clair a Rising Badge.', 'Após a ligação de Elm, volte ao laboratório em New Bark para receber a Master Ball, depois vá ao Dance Theater em Ecruteak e derrote as cinco Kimono Girls em sequência.', 'Em HeartGold, siga até a Bell Tower para encontrar Ho-Oh, enquanto em SoulSilver você deve atravessar as Whirl Islands para encontrar Lugia, então capture ou derrote o Pokémon da sua versão.', 'Volte a New Bark, use Surf a leste da cidade e atravesse as Tohjo Falls com Waterfall, depois continue pelas Routes 27 e 26 até a entrada da Victory Road.', 'Apresente suas oito insígnias aos guardas e atravesse a Victory Road, enfrentando seu rival perto da saída para chegar ao Indigo Plateau.'), true)
FROM public.detonados AS origem
JOIN public.pokemon AS alvo ON alvo.slug IN ('pokemon-heart-gold', 'pokemon-soul-silver')
WHERE origem.slug = 'pokemon-gold'
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Ajusta apenas a frase antiga, preservando o restante de cada detonado de Kanto.
UPDATE public.detonados
SET walkthrough = jsonb_set(walkthrough, '{Elite Four,0}',
    to_jsonb(replace(walkthrough #>> '{Elite Four,0}',
        'A Elite Four reúne quatro treinadores de Kanto',
        'A Elite Four reúne quatro dos melhores treinadores de Kanto')))
WHERE slug IN ('pokemon-blue', 'pokemon-red', 'pokemon-green', 'pokemon-yellow',
    'pokemon-fire-red', 'pokemon-leaf-green', 'pokemon-let-s-go-pikachu', 'pokemon-let-s-go-eevee')
  AND walkthrough #>> '{Elite Four,0}' LIKE 'A Elite Four reúne quatro treinadores de Kanto%';

-- Atualiza a pontuação da Elite Four sem alterar os demais textos.
UPDATE public.detonados
SET walkthrough = jsonb_set(walkthrough, '{Elite Four,0}',
    to_jsonb(replace(replace(walkthrough #>> '{Elite Four,0}',
        'sequência: Lorelei,', 'sequência, sendo Lorelei,'),
        'sequência: Will,', 'sequência, sendo Will,')))
WHERE slug IN ('pokemon-blue', 'pokemon-red', 'pokemon-green', 'pokemon-yellow',
    'pokemon-fire-red', 'pokemon-leaf-green', 'pokemon-let-s-go-pikachu', 'pokemon-let-s-go-eevee',
    'pokemon-gold', 'pokemon-silver', 'pokemon-heart-gold', 'pokemon-soul-silver')
  AND (walkthrough #>> '{Elite Four,0}' LIKE '%sequência: Lorelei,%'
       OR walkthrough #>> '{Elite Four,0}' LIKE '%sequência: Will,%');

-- Campanha principal de Pokémon Ruby e Sapphire, até o Champion.
WITH capitulos_hoenn (ordem, titulo, passos) AS (
VALUES
(1, 'Littleroot Town', ARRAY['O Professor Birch apresenta o mundo Pokémon e pergunta seu nome, depois você chega à sua nova casa em Littleroot Town.', 'Acerte o relógio no quarto e conheça o vizinho, depois siga ao norte pela Route 101 para ajudar o Professor Birch e escolha Treecko, Torchic ou Mudkip para enfrentar o Pokémon selvagem.', 'No laboratório, Birch pedirá que você procure seu rival, então atravesse Oldale Town e siga pela Route 103 para enfrentá-lo, depois volte ao laboratório para receber a Pokédex e Poké Balls.']),
(2, 'Petalburg City', ARRAY['Saia de Oldale pelo oeste e atravesse a Route 102 até Petalburg City, depois entre no ginásio para encontrar seu pai, Norman.', 'Acompanhe Wally enquanto ele captura seu primeiro Pokémon e volte ao ginásio, depois siga para oeste pela Route 104 e entre na Petalburg Woods.', 'Na floresta, ajude o funcionário da Devon contra um membro da equipe adversária e continue ao norte pela Route 104 até Rustboro City.']),
(3, 'Rustboro City', ARRAY['No ginásio de Rustboro, derrote Roxanne, líder especialista no tipo Pedra, para conquistar a Stone Badge.', 'Siga pela Route 116 até o Rusturf Tunnel e derrote o membro da equipe que roubou os Devon Goods, libertando também Peeko, o Pokémon de Mr. Briney.', 'Volte a Rustboro e entregue os Devon Goods ao funcionário, depois converse com o presidente da Devon para receber a PokéNav e as encomendas para Steven e Captain Stern.', 'Atravesse a Petalburg Woods em direção ao sul e fale com Mr. Briney na casa perto da praia para viajar de barco até Dewford Town.']),
(4, 'Dewford Town', ARRAY['Entre no ginásio de Dewford e derrote Brawly, líder especialista no tipo Lutador, para receber a Knuckle Badge.', 'Siga ao norte até a Granite Cave e receba HM05 Flash na entrada, depois atravesse a caverna e entregue a carta a Steven.', 'Volte ao barco e peça a Mr. Briney que leve você a Slateport City.']),
(5, 'Slateport City', ARRAY['Em Slateport, vá ao estaleiro e converse com Dock, depois entre no Oceanic Museum para encontrar Captain Stern.', 'Derrote os membros da equipe adversária e entregue os Devon Goods ao capitão, depois saia da cidade pelo norte.', 'Siga pelas Routes 110 e 103, enfrente seu rival no caminho e continue até Mauville City.']),
(6, 'Mauville City', ARRAY['Em Mauville, fale com Wally diante do ginásio e vença a batalha, depois entre e derrote Wattson, líder especialista no tipo Elétrico, para receber a Dynamo Badge.', 'Em uma casa da cidade, receba HM06 Rock Smash e pegue uma bicicleta na loja, depois saia pelo norte em direção à Route 111.', 'Como o deserto está bloqueado, siga pela Route 112 e atravesse o Fiery Path, depois continue pelas Routes 113 e 114 até Fallarbor Town.']),
(7, 'Fallarbor Town', ARRAY['Siga a oeste pela Route 114 e entre no Meteor Falls, onde você encontrará membros da equipe adversária com o Professor Cozmo.', 'Após os acontecimentos na caverna, volte à Route 112 e use o teleférico para subir ao Mt. Chimney.', 'No topo, enfrente a equipe adversária e seu líder para impedir seus planos, depois desça pelo Jagged Pass até Lavaridge Town.']),
(8, 'Lavaridge Town', ARRAY['No ginásio de Lavaridge, atravesse as passagens e derrote Flannery, líder especialista no tipo Fogo, para conquistar a Heat Badge.', 'Ao sair, receba os Go-Goggles do seu rival, depois retorne a Petalburg City para desafiar Norman.']),
(9, 'Petalburg Gym', ARRAY['Entre no ginásio de Petalburg com quatro insígnias, atravesse as salas e derrote Norman, líder especialista no tipo Normal, para receber a Balance Badge.', 'Na casa de Wally ao lado do ginásio, receba HM03 Surf e ensine o golpe a um Pokémon, depois volte a Mauville City e use Surf a leste pela Route 118.', 'Continue ao norte pela Route 119 até encontrar o Weather Institute, onde você deve derrotar a equipe adversária e libertar os pesquisadores.', 'Atravesse a ponte, vença seu rival para receber HM02 Fly e siga até Fortree City.']),
(10, 'Fortree City', ARRAY['O caminho para o ginásio de Fortree está bloqueado, então saia pelo leste e encontre Steven na ponte da Route 120 para receber o Devon Scope.', 'Use o Devon Scope para revelar o Kecleon invisível e volte ao ginásio, depois revele o Pokémon que bloqueia a entrada.', 'Derrote Winona, líder especialista no tipo Voador, para conquistar a Feather Badge e siga pelas Routes 120 e 121 até Lilycove City.']),
(11, 'Lilycove City', ARRAY['Saia de Lilycove pelo oeste e use Surf ao sul na Route 121 para chegar ao Mt. Pyre, depois suba ao topo e enfrente a equipe adversária.', 'Voe até Slateport e encontre Captain Stern no porto, onde a equipe roubará um submarino, depois volte a Lilycove e entre no esconderijo ao norte da praia.', 'Atravesse o esconderijo e enfrente os membros da equipe, depois saia e use Surf a leste até Mossdeep City.']),
(12, 'Mossdeep City', ARRAY['No ginásio de Mossdeep, vença a batalha em dupla contra Tate e Liza, especialistas no tipo Psíquico, para receber a Mind Badge.', 'Fale com Steven em sua casa para receber HM08 Dive, depois use Surf para seguir ao sul e mergulhe nas águas profundas da Route 128.', 'Encontre o submarino e entre na Seafloor Cavern, usando Strength e Rock Smash para atravessar os obstáculos, depois derrote o líder da equipe adversária.', 'Após o despertar de Groudon em Ruby ou Kyogre em Sapphire, siga até Sootopolis City usando Dive na entrada submersa cercada por rochas.']),
(13, 'Sootopolis City', ARRAY['Em Sootopolis, encontre Steven e entre na Cave of Origin para pegar HM07 Waterfall e chegar ao Pokémon lendário da sua versão.', 'Capture ou derrote Groudon em Ruby ou Kyogre em Sapphire, depois saia da caverna e entre no ginásio.', 'Atravesse os pisos de gelo e derrote Wallace, líder especialista no tipo Água, para conquistar a Rain Badge.', 'Com as oito insígnias, siga pela Route 128 até Ever Grande City e use Waterfall para subir a cachoeira, depois atravesse a Victory Road e enfrente Wally perto da saída para chegar à Liga Pokémon.']),
(14, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Hoenn que devem ser enfrentados em sequência, sendo Sidney especialista no tipo Sombrio e Phoebe especialista no tipo Fantasma.', 'Os próximos desafios são Glacia, especialista no tipo Gelo que também usa Pokémon de Água, e Drake, especialista no tipo Dragão.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(15, 'Champion', ARRAY['Após vencer Drake, enfrente o Champion da Liga Pokémon, Steven, que usa uma equipe com destaque para Pokémon dos tipos Aço e Pedra.', 'A batalha contra o Champion acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, Steven acompanhará você até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.'])
), guia_hoenn AS (
    SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough
    FROM capitulos_hoenn
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough
FROM public.pokemon AS jogo CROSS JOIN guia_hoenn AS guia
WHERE jogo.slug IN ('pokemon-ruby', 'pokemon-sapphire')
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Campanha de Pokémon Emerald, com seus eventos próprios.
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT alvo.slug, origem.caps, jsonb_set(jsonb_set(jsonb_set(jsonb_set(origem.walkthrough, ARRAY['Lilycove City'], jsonb_build_array('Saia de Lilycove pelo oeste e use Surf ao sul na Route 121 para chegar ao Mt. Pyre, depois suba ao topo e enfrente os membros da Team Aqua para receber o Magma Emblem.', 'Volte ao Mt. Chimney e desça pelo Jagged Pass até o emblema revelar a entrada do esconderijo da Team Magma, depois atravesse o local e enfrente Maxie.', 'Vá até o porto de Slateport e encontre Captain Stern, depois que a Team Aqua roubar o submarino, volte à praia de Lilycove e entre no esconderijo da equipe.', 'Atravesse o esconderijo e derrote os membros da Team Aqua, depois saia e use Surf a leste até Mossdeep City.'), true), ARRAY['Mossdeep City'], jsonb_build_array('No ginásio de Mossdeep, vença a batalha em dupla contra Tate e Liza, especialistas no tipo Psíquico, para receber a Mind Badge.', 'Vá ao Space Center e ajude Steven a enfrentar a Team Magma, depois fale com ele em sua casa para receber HM08 Dive.', 'Use Surf para seguir ao sul, mergulhe nas águas profundas da Route 128 e encontre o submarino na entrada da Seafloor Cavern.', 'Atravesse a caverna com Strength e Rock Smash e enfrente Archie, líder da Team Aqua, depois do despertar de Kyogre siga até Sootopolis City pela entrada submersa cercada por rochas.'), true), ARRAY['Sootopolis City'], jsonb_build_array('Em Sootopolis, encontre Steven e fale com Wallace na Cave of Origin, depois indique o Sky Pillar como o lugar onde Rayquaza pode ser encontrado.', 'Siga até o Sky Pillar na Route 131, a leste de Pacifidlog, e suba até o topo para despertar Rayquaza, depois volte a Sootopolis.', 'Após Rayquaza interromper o confronto entre Groudon e Kyogre, fale com Wallace para receber HM07 Waterfall e entrar no ginásio.', 'Atravesse os pisos de gelo e derrote Juan, líder especialista no tipo Água, para conquistar a Rain Badge.', 'Com as oito insígnias, siga pela Route 128 até Ever Grande City e use Waterfall para subir a cachoeira, depois atravesse a Victory Road e enfrente Wally para chegar à Liga Pokémon.'), true), ARRAY['Champion'], jsonb_build_array('Após vencer Drake, enfrente o Champion da Liga Pokémon, Wallace, especialista no tipo Água.', 'A batalha contra o Champion acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, Wallace acompanhará você até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.'), true)
FROM public.detonados AS origem
JOIN public.pokemon AS alvo ON alvo.slug = 'pokemon-emerald'
WHERE origem.slug = 'pokemon-ruby'
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Campanha de Pokémon Omega Ruby e Alpha Sapphire, até o Champion.
WITH capitulos_hoenn (ordem, titulo, passos) AS (
VALUES
(1, 'Littleroot Town', ARRAY['O Professor Birch apresenta o mundo Pokémon e pergunta seu nome, depois você chega à sua nova casa em Littleroot Town.', 'Acerte o relógio no quarto e conheça o vizinho, depois siga ao norte pela Route 101 para ajudar o Professor Birch e escolha Treecko, Torchic ou Mudkip para enfrentar o Pokémon selvagem.', 'No laboratório, Birch pedirá que você procure seu rival, então atravesse Oldale Town e siga pela Route 103 para enfrentá-lo, depois volte ao laboratório para receber a Pokédex e Poké Balls.']),
(2, 'Petalburg City', ARRAY['Saia de Oldale pelo oeste e atravesse a Route 102 até Petalburg City, depois entre no ginásio para encontrar seu pai, Norman.', 'Acompanhe Wally enquanto ele captura seu primeiro Pokémon e volte ao ginásio, depois siga para oeste pela Route 104 e entre na Petalburg Woods.', 'Na floresta, ajude o funcionário da Devon contra um membro da equipe adversária e continue ao norte pela Route 104 até Rustboro City.']),
(3, 'Rustboro City', ARRAY['No ginásio de Rustboro, derrote Roxanne, líder especialista no tipo Pedra, para conquistar a Stone Badge.', 'Siga pela Route 116 até o Rusturf Tunnel e derrote o membro da equipe que roubou os Devon Goods, libertando também Peeko, o Pokémon de Mr. Briney.', 'Volte a Rustboro e entregue os Devon Goods ao funcionário, depois converse com o presidente da Devon para receber a PokéNav e as encomendas para Steven e Captain Stern.', 'Atravesse a Petalburg Woods em direção ao sul e fale com Mr. Briney na casa perto da praia para viajar de barco até Dewford Town.']),
(4, 'Dewford Town', ARRAY['Entre no ginásio de Dewford e derrote Brawly, líder especialista no tipo Lutador, para receber a Knuckle Badge.', 'Siga ao norte até a Granite Cave e receba HM05 Flash na entrada, depois atravesse a caverna e entregue a carta a Steven.', 'Volte ao barco e peça a Mr. Briney que leve você a Slateport City.']),
(5, 'Slateport City', ARRAY['Em Slateport, vá ao estaleiro e converse com Dock, depois entre no Oceanic Museum para encontrar Captain Stern.', 'Derrote os membros da equipe adversária e entregue os Devon Goods ao capitão, depois saia da cidade pelo norte.', 'Siga pelas Routes 110 e 103, enfrente seu rival no caminho e continue até Mauville City.']),
(6, 'Mauville City', ARRAY['Em Mauville, fale com Wally diante do ginásio e vença a batalha, depois entre e derrote Wattson, líder especialista no tipo Elétrico, para receber a Dynamo Badge.', 'Em uma casa da cidade, receba HM06 Rock Smash e pegue uma bicicleta na loja, depois saia pelo norte em direção à Route 111.', 'Como o deserto está bloqueado, siga pela Route 112 e atravesse o Fiery Path, depois continue pelas Routes 113 e 114 até Fallarbor Town.']),
(7, 'Fallarbor Town', ARRAY['Siga a oeste pela Route 114 e entre no Meteor Falls, onde você encontrará membros da equipe adversária com o Professor Cozmo.', 'Após os acontecimentos na caverna, volte à Route 112 e use o teleférico para subir ao Mt. Chimney.', 'No topo, enfrente a equipe adversária e seu líder para impedir seus planos, depois desça pelo Jagged Pass até Lavaridge Town.']),
(8, 'Lavaridge Town', ARRAY['No ginásio de Lavaridge, atravesse as passagens e derrote Flannery, líder especialista no tipo Fogo, para conquistar a Heat Badge.', 'Ao sair, receba os Go-Goggles do seu rival, depois retorne a Petalburg City para desafiar Norman.']),
(9, 'Petalburg Gym', ARRAY['Entre no ginásio de Petalburg com quatro insígnias, atravesse as salas e derrote Norman, líder especialista no tipo Normal, para receber a Balance Badge.', 'Na casa de Wally ao lado do ginásio, receba HM03 Surf e ensine o golpe a um Pokémon, depois volte a Mauville City e use Surf a leste pela Route 118.', 'Continue ao norte pela Route 119 até encontrar o Weather Institute, onde você deve derrotar a equipe adversária e libertar os pesquisadores.', 'Atravesse a ponte, vença seu rival para receber HM02 Fly e siga até Fortree City.']),
(10, 'Fortree City', ARRAY['O caminho para o ginásio de Fortree está bloqueado, então saia pelo leste e encontre Steven na ponte da Route 120 para receber o Devon Scope.', 'Use o Devon Scope para revelar o Kecleon invisível e volte ao ginásio, depois revele o Pokémon que bloqueia a entrada.', 'Derrote Winona, líder especialista no tipo Voador, para conquistar a Feather Badge e siga pelas Routes 120 e 121 até Lilycove City.']),
(11, 'Lilycove City', ARRAY['Saia de Lilycove pelo oeste e use Surf ao sul na Route 121 para chegar ao Mt. Pyre, depois suba ao topo e enfrente a equipe adversária.', 'Voe até Slateport e encontre Captain Stern no porto, onde a equipe roubará um submarino, depois volte a Lilycove e entre no esconderijo ao norte da praia.', 'Atravesse o esconderijo e enfrente os membros da equipe, depois saia e use Surf a leste até Mossdeep City.']),
(12, 'Mossdeep City', ARRAY['No ginásio de Mossdeep, vença a batalha em dupla contra Tate e Liza, especialistas no tipo Psíquico, para receber a Mind Badge.', 'Fale com Steven em sua casa para receber HM08 Dive, depois use Surf para seguir ao sul e mergulhe nas águas profundas da Route 128.', 'Encontre o submarino e entre na Seafloor Cavern, usando Strength e Rock Smash para atravessar os obstáculos, depois derrote o líder da equipe adversária.', 'Após o despertar de Groudon em Ruby ou Kyogre em Sapphire, siga até Sootopolis City usando Dive na entrada submersa cercada por rochas.']),
(13, 'Sootopolis City', ARRAY['Em Sootopolis, encontre Steven e entre na Cave of Origin para pegar HM07 Waterfall e chegar ao Pokémon lendário da sua versão.', 'Capture ou derrote Groudon em Ruby ou Kyogre em Sapphire, depois saia da caverna e entre no ginásio.', 'Atravesse os pisos de gelo e derrote Wallace, líder especialista no tipo Água, para conquistar a Rain Badge.', 'Com as oito insígnias, siga pela Route 128 até Ever Grande City e use Waterfall para subir a cachoeira, depois atravesse a Victory Road e enfrente Wally perto da saída para chegar à Liga Pokémon.']),
(14, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Hoenn que devem ser enfrentados em sequência, sendo Sidney especialista no tipo Sombrio e Phoebe especialista no tipo Fantasma.', 'Os próximos desafios são Glacia, especialista no tipo Gelo que também usa Pokémon de Água, e Drake, especialista no tipo Dragão.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(15, 'Champion', ARRAY['Após vencer Drake, enfrente o Champion da Liga Pokémon, Steven, que usa uma equipe com destaque para Pokémon dos tipos Aço e Pedra.', 'A batalha contra o Champion acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, Steven acompanhará você até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.'])
), guia_hoenn AS (
    SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough
    FROM capitulos_hoenn
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(guia.walkthrough, ARRAY['Littleroot Town'], jsonb_build_array('O Professor Birch apresenta o mundo Pokémon e pergunta seu nome, depois você chega à sua nova casa em Littleroot Town.', 'Suba ao quarto e examine o relógio, depois conheça seu vizinho e siga ao norte pela Route 101 para ajudar o Professor Birch, escolhendo Treecko, Torchic ou Mudkip para enfrentar o Pokémon selvagem.', 'No laboratório, Birch pedirá que você procure seu rival, então atravesse Oldale Town e siga pela Route 103 para enfrentá-lo, depois volte ao laboratório para receber a Pokédex e Poké Balls.'), true), ARRAY['Rustboro City'], jsonb_build_array('No ginásio de Rustboro, derrote Roxanne, líder especialista no tipo Pedra, para conquistar a Stone Badge.', 'Siga pela Route 116 até o Rusturf Tunnel e derrote o membro da equipe que roubou os Devon Parts, libertando também Peeko, o Pokémon de Mr. Briney.', 'Volte a Rustboro e entregue os Devon Parts ao funcionário, depois converse com o presidente da Devon para receber uma carta para Steven.', 'Atravesse a Petalburg Woods em direção ao sul e fale com Mr. Briney na casa perto da praia para viajar de barco até Dewford Town.'), true), ARRAY['Dewford Town'], jsonb_build_array('Entre no ginásio de Dewford e derrote Brawly, líder especialista no tipo Lutador, para receber a Knuckle Badge.', 'Siga ao norte até a Granite Cave e receba TM70 Flash na entrada, depois entre na sala das pinturas e entregue a carta a Steven.', 'Volte ao barco e peça a Mr. Briney que leve você à Route 109, de onde poderá seguir ao norte até Slateport City.'), true), ARRAY['Slateport City'], jsonb_build_array('Em Slateport, vá ao estaleiro e converse com Dock, depois entre no Oceanic Museum para encontrar Captain Stern.', 'Derrote os membros da equipe adversária e entregue os Devon Parts ao capitão, depois saia da cidade pelo norte.', 'Siga pela Route 110, enfrente seu rival no caminho e continue até Mauville City.'), true), ARRAY['Mauville City'], jsonb_build_array('Em Mauville, fale com Wally diante do ginásio e vença a batalha, depois receba HM06 Rock Smash do tio dele.', 'Entre no ginásio e derrote Wattson, líder especialista no tipo Elétrico, para receber a Dynamo Badge, depois pegue uma bicicleta na loja e saia pelo norte em direção à Route 111.', 'Quebre as pedras com Rock Smash e siga até a Route 112, onde seu rival entregará HM04 Strength, depois atravesse o Fiery Path e continue pelas Routes 113 e 114 até Fallarbor Town.'), true), ARRAY['Petalburg Gym'], jsonb_build_array('Entre no ginásio de Petalburg com quatro insígnias, atravesse as salas e derrote Norman, líder especialista no tipo Normal, para receber a Balance Badge.', 'Ao sair, receba HM03 Surf do pai de Wally, depois volte a Mauville City e use Surf a leste pela Route 118.', 'Encontre Steven e viaje com ele até a Southern Island, onde vocês enfrentarão a equipe adversária para proteger Latios em Omega Ruby ou Latias em Alpha Sapphire.', 'Volte à Route 118 e continue ao norte pela Route 119 até o Weather Institute, depois derrote a equipe adversária e liberte os pesquisadores.', 'Atravesse a ponte, vença seu rival para receber HM02 Fly e siga até Fortree City.'), true), ARRAY['Lilycove City'], jsonb_build_array('Enfrente seu rival perto do Department Store em Lilycove, depois volte à Route 121 e use Surf ao sul para chegar ao Mt. Pyre.', 'Suba ao topo do Mt. Pyre e enfrente a equipe adversária, depois voe até Slateport e encontre Captain Stern no porto, onde a equipe roubará um submarino.', 'Volte a Lilycove e entre no esconderijo ao norte da praia, atravesse as salas e enfrente os membros da equipe, depois use Surf a leste até Mossdeep City.'), true), ARRAY['Mossdeep City'], jsonb_build_array('No ginásio de Mossdeep, vença a batalha em dupla contra Tate e Liza, especialistas no tipo Psíquico, para receber a Mind Badge.', 'Após o acontecimento no mar, encontre Steven em sua casa para receber HM07 Dive e o equipamento de mergulho.', 'Use Surf para seguir ao sul, mergulhe nas águas profundas da Route 128 e encontre o submarino na entrada da Seafloor Cavern.', 'Atravesse a caverna usando Strength e Rock Smash e enfrente o líder da equipe adversária, depois do despertar de Groudon ou Kyogre siga até Sootopolis pela entrada submersa cercada por rochas.'), true), ARRAY['Sootopolis City'], jsonb_build_array('Em Sootopolis, encontre Steven e Wallace perto da Cave of Origin e receba o traje que permite se aproximar do Pokémon lendário.', 'Entre na caverna e encontre Groudon em Omega Ruby ou Kyogre em Alpha Sapphire, depois enfrente sua forma Primal e capture-o ou derrote-o para encerrar a alteração do clima.', 'Entre no ginásio, atravesse os pisos de gelo e derrote Wallace, líder especialista no tipo Água, para conquistar a Rain Badge e receber HM05 Waterfall.', 'Com as oito insígnias, siga pela Route 128 até Ever Grande City e use Waterfall para subir a cachoeira, depois atravesse a Victory Road e enfrente Wally para chegar à Liga Pokémon.'), true)
FROM public.pokemon AS jogo CROSS JOIN guia_hoenn AS guia
WHERE jogo.slug IN ('pokemon-omega-ruby', 'pokemon-alpha-sapphire')
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Campanhas de Pokémon em Sinnoh, até o Champion.
WITH capitulos_sinnoh (versao, ordem, titulo, passos) AS (
VALUES
('original', 1, 'Twinleaf Town', ARRAY['O Professor Rowan apresenta o mundo Pokémon e pergunta seu nome, depois você começa a jornada em Twinleaf Town.', 'Encontre seu amigo e acompanhe-o até o Lake Verity, onde vocês escolherão entre Turtwig, Chimchar e Piplup para enfrentar Pokémon selvagens.', 'Siga pela Route 201 até Sandgem Town e fale com Rowan no laboratório para receber seu Pokémon e a Pokédex, depois volte para se despedir de sua mãe.']),
('original', 2, 'Jubilife City', ARRAY['Volte a Sandgem e siga ao norte pela Route 202, onde o assistente de Rowan mostrará como capturar Pokémon, depois continue até Jubilife City.', 'Na escola de treinadores, entregue a encomenda da sua mãe ao seu rival e receba o mapa de Sinnoh, depois saia pelo leste pela Route 203.', 'Enfrente seu rival, atravesse o Oreburgh Gate e continue até Oreburgh City.']),
('original', 3, 'Oreburgh City', ARRAY['Encontre Roark na Oreburgh Mine ao sul da cidade e volte ao ginásio para desafiá-lo.', 'Derrote Roark, líder especialista no tipo Pedra, para conquistar a Coal Badge, depois retorne a Jubilife City pelo Oreburgh Gate.', 'Ajude o Professor Rowan e seu assistente a enfrentar a Team Galactic ao norte da cidade, depois siga pela Route 204 e atravesse o Ravaged Path até Floaroma Town.']),
('original', 4, 'Eterna City', ARRAY['A leste de Floaroma, derrote o membro da Team Galactic no Valley Windworks e procure a Works Key com os membros da equipe no Floaroma Meadow.', 'Abra a entrada do Valley Windworks e derrote os membros da equipe e a comandante Mars, depois siga pela Route 205 e atravesse a Eterna Forest até Eterna City.', 'Derrote Gardenia, líder especialista no tipo Planta, para receber a Forest Badge, depois use Cut para entrar no prédio da Team Galactic e derrotar a comandante Jupiter.', 'Receba uma bicicleta na loja e atravesse a Cycling Road pela Route 206, depois siga pela Route 207 e atravesse o Mt. Coronet até Hearthome City.']),
('original', 5, 'Veilstone City', ARRAY['Em Hearthome City, encontre Fantina perto do Contest Hall, depois enfrente seu rival na saída leste e siga pelas Routes 209 e 210 até Solaceon Town.', 'Continue ao norte pela Route 210 e siga pela Route 215 até Veilstone City, depois entre no ginásio.', 'Derrote Maylene, líder especialista no tipo Lutador, para conquistar a Cobble Badge, depois ajude o assistente de Rowan a recuperar a Pokédex roubada pela Team Galactic e obtenha Fly no depósito.', 'Saia de Veilstone pelo sul e siga pelas Routes 214 e 213 até Pastoria City.']),
('original', 6, 'Pastoria City', ARRAY['Em Pastoria City, derrote Crasher Wake, líder especialista no tipo Água, para receber a Fen Badge, depois fale com o membro da Team Galactic perto da entrada do Great Marsh.', 'Persiga o membro da equipe para leste até enfrentá-lo, depois encontre Cynthia e receba o SecretPotion para afastar os Psyduck que bloqueiam a Route 210.', 'Pegue Defog na área de entrada do Great Marsh, depois volte à Route 210, use o remédio nos Psyduck e atravesse o caminho com neblina até Celestic Town.']),
('original', 7, 'Hearthome City', ARRAY['Em Celestic Town, enfrente o membro da Team Galactic diante das ruínas e examine as pinturas no interior para receber Surf da avó de Cynthia.', 'Volte a Hearthome City e entre no ginásio, depois derrote Fantina, líder especialista no tipo Fantasma, para conquistar a Relic Badge.', 'Volte a Jubilife City e siga para oeste pela Route 218, usando Surf para atravessar a água até Canalave City.']),
('original', 8, 'Canalave City', ARRAY['Ao atravessar a ponte de Canalave, enfrente seu rival e entre no ginásio, depois derrote Byron, líder especialista no tipo Aço, para conquistar a Mine Badge.', 'Encontre o Professor Rowan, seu assistente e seu rival no último andar da biblioteca, onde vocês descobrirão que algo aconteceu no Lake Valor.', 'Siga ao Lake Valor e enfrente a Team Galactic, depois vá ao Lake Verity perto de Twinleaf Town e ajude o assistente de Rowan a derrotar a equipe.', 'Para continuar, obtenha Strength na Lost Tower da Route 209 e siga a oeste de Celestic Town pela Route 211, atravessando o Mt. Coronet em direção às rotas nevadas.']),
('original', 9, 'Snowpoint City', ARRAY['Atravesse as Routes 216 e 217 e procure Rock Climb perto da casa na Route 217, depois continue pela Acuity Lakefront até Snowpoint City.', 'No ginásio, destrua as bolas de neve e derrote Candice, líder especialista no tipo Gelo, para conquistar a Icicle Badge.', 'Vá ao Lake Acuity e encontre seu rival e a comandante Jupiter, depois siga para Veilstone City para investigar a sede da Team Galactic.']),
('original', 10, 'Veilstone Galactic', ARRAY['Fale com o membro da Team Galactic diante da sede para obter a Storage Key e abra o depósito no oeste de Veilstone.', 'Atravesse o depósito para conseguir a Galactic Key, depois use-a na sede e continue até enfrentar Cyrus.', 'Encontre os Pokémon dos lagos no laboratório e derrote Saturn, depois aperte o botão para libertá-los e siga ao Mt. Coronet.']),
('original', 11, 'Spear Pillar', ARRAY['Entre no Mt. Coronet pela Route 207 ou Route 208 e use Surf, Strength e Rock Climb para alcançar o caminho até o topo.', 'No Spear Pillar, enfrente a Team Galactic e lute ao lado do seu rival contra as comandantes, depois derrote Cyrus.', 'Enfrente Dialga em Diamond ou Brilliant Diamond e Palkia em Pearl ou Shining Pearl, capturando ou derrotando o Pokémon para encerrar os planos da Team Galactic.', 'Saia da montanha e siga pela Route 222 até Sunyshore City.']),
('original', 12, 'Sunyshore City', ARRAY['Em Sunyshore City, encontre Volkner no farol e fale com ele para que retorne ao ginásio.', 'Entre no ginásio e derrote Volkner, líder especialista no tipo Elétrico, para conquistar a Beacon Badge, depois fale com Jasmine na praia ao norte para receber Waterfall.', 'Use Surf e Waterfall pela Route 223 até a Pokémon League, depois atravesse a Victory Road e derrote os treinadores pelo caminho para chegar à entrada da Liga.']),
('original', 13, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Sinnoh que devem ser enfrentados em sequência, sendo Aaron especialista no tipo Inseto e Bertha especialista no tipo Terra.', 'Os próximos desafios são Flint, especialista no tipo Fogo, e Lucian, especialista no tipo Psíquico.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
('original', 14, 'Champion', ARRAY['Após vencer Lucian, enfrente a Champion da Liga Pokémon, Cynthia, que usa uma equipe de diferentes tipos e tem Garchomp como um de seus Pokémon.', 'A batalha contra a Champion acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, Cynthia acompanhará você até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.']),
('platinum', 1, 'Twinleaf Town', ARRAY['O Professor Rowan apresenta o mundo Pokémon e pergunta seu nome, depois você começa a jornada em Twinleaf Town.', 'Encontre seu amigo e siga com ele até o norte da Route 201, onde o Professor Rowan permitirá que vocês escolham entre Turtwig, Chimchar e Piplup antes da primeira batalha.', 'Acompanhe seu amigo até o Lake Verity, depois siga para Sandgem Town e visite o laboratório de Rowan para receber a Pokédex, voltando a Twinleaf para se despedir de sua mãe.']),
('platinum', 2, 'Jubilife City', ARRAY['Volte a Sandgem e siga ao norte pela Route 202, onde o assistente de Rowan mostrará como capturar Pokémon, depois continue até Jubilife City.', 'Na escola de treinadores, entregue a encomenda da sua mãe ao seu rival e receba o mapa de Sinnoh, depois saia pelo leste pela Route 203.', 'Enfrente seu rival, atravesse o Oreburgh Gate e continue até Oreburgh City.']),
('platinum', 3, 'Oreburgh City', ARRAY['Encontre Roark na Oreburgh Mine ao sul da cidade e volte ao ginásio para desafiá-lo.', 'Derrote Roark, líder especialista no tipo Pedra, para conquistar a Coal Badge, depois retorne a Jubilife City pelo Oreburgh Gate.', 'Ajude o Professor Rowan e seu assistente a enfrentar a Team Galactic ao norte da cidade, depois siga pela Route 204 e atravesse o Ravaged Path até Floaroma Town.']),
('platinum', 4, 'Eterna City', ARRAY['A leste de Floaroma, derrote o membro da Team Galactic no Valley Windworks e procure a Works Key com os membros da equipe no Floaroma Meadow.', 'Abra a entrada do Valley Windworks e derrote os membros da equipe e a comandante Mars, depois siga pela Route 205 e atravesse a Eterna Forest até Eterna City.', 'Derrote Gardenia, líder especialista no tipo Planta, para receber a Forest Badge, depois use Cut para entrar no prédio da Team Galactic e derrotar a comandante Jupiter.', 'Receba uma bicicleta na loja e atravesse a Cycling Road pela Route 206, depois siga pela Route 207 e atravesse o Mt. Coronet até Hearthome City.']),
('platinum', 5, 'Hearthome City', ARRAY['Em Hearthome City, encontre Fantina perto do Contest Hall e entre no ginásio, onde você deve seguir as portas com os símbolos indicados.', 'Derrote Fantina, líder especialista no tipo Fantasma, para conquistar a Relic Badge, depois enfrente seu rival na saída leste e siga pelas Routes 209 e 210 até Solaceon Town.', 'Continue pela Route 210 e siga pela Route 215 até Veilstone City.']),
('platinum', 6, 'Veilstone City', ARRAY['Em Veilstone City, entre no ginásio e derrote Maylene, líder especialista no tipo Lutador, para conquistar a Cobble Badge.', 'Ajude o assistente de Rowan a recuperar a Pokédex roubada pela Team Galactic e obtenha Fly no depósito, depois saia pelo sul e siga pelas Routes 214 e 213 até Pastoria City.']),
('platinum', 7, 'Pastoria City', ARRAY['Em Pastoria City, derrote Crasher Wake, líder especialista no tipo Água, para receber a Fen Badge, depois fale com o membro da Team Galactic perto da entrada do Great Marsh.', 'Persiga o membro da equipe até enfrentá-lo, depois encontre Cynthia e receba o SecretPotion para afastar os Psyduck que bloqueiam a Route 210.', 'Obtenha Defog nas ruínas de Solaceon, depois volte à Route 210, use o remédio nos Psyduck e atravesse o caminho com neblina até Celestic Town.']),
('platinum', 8, 'Celestic Town', ARRAY['Em Celestic Town, enfrente o membro da Team Galactic diante das ruínas e examine as pinturas no interior, depois enfrente Cyrus e receba Surf da avó de Cynthia.', 'Volte a Jubilife City e siga para oeste pela Route 218, usando Surf para atravessar a água até Canalave City.']),
('platinum', 9, 'Canalave City', ARRAY['Ao atravessar a ponte de Canalave, enfrente seu rival e entre no ginásio, depois derrote Byron, líder especialista no tipo Aço, para conquistar a Mine Badge.', 'Viaje de barco para Iron Island e receba Strength de Riley na entrada, depois volte a Canalave e encontre o Professor Rowan, seu assistente e seu rival na biblioteca.', 'Siga ao Lake Valor e enfrente a Team Galactic, depois vá ao Lake Verity perto de Twinleaf Town e ajude o assistente de Rowan a derrotar a equipe.', 'Siga a oeste de Celestic Town pela Route 211 e atravesse o Mt. Coronet em direção às rotas nevadas.']),
('platinum', 10, 'Snowpoint City', ARRAY['Atravesse as Routes 216 e 217 e procure Rock Climb perto da casa na Route 217, depois continue pela Acuity Lakefront até Snowpoint City.', 'No ginásio, destrua as bolas de neve e derrote Candice, líder especialista no tipo Gelo, para conquistar a Icicle Badge.', 'Vá ao Lake Acuity e encontre seu rival e a comandante Jupiter, depois siga para Veilstone City para investigar a sede da Team Galactic.']),
('platinum', 11, 'Veilstone Galactic', ARRAY['Fale com o membro da Team Galactic diante da sede para obter a Storage Key e abra o depósito no oeste de Veilstone.', 'Atravesse o depósito para conseguir a Galactic Key, depois use-a na sede e continue até enfrentar Cyrus.', 'Encontre os Pokémon dos lagos no laboratório e derrote Saturn, depois aperte o botão para libertá-los e siga ao Mt. Coronet.']),
('platinum', 12, 'Spear Pillar', ARRAY['Entre no Mt. Coronet pela Route 207 ou Route 208 e use Surf, Strength e Rock Climb para alcançar o caminho até o topo.', 'No Spear Pillar, enfrente a Team Galactic e lute ao lado do seu rival contra as comandantes, depois acompanhe Cynthia pelo portal até o Distortion World.', 'Atravesse as plataformas, use Strength para mover as pedras até os locais indicados pelos Pokémon dos lagos e derrote Cyrus.', 'Enfrente Giratina e saia pelo portal com Cynthia, depois fale com o Professor Rowan em Sandgem Town e siga pela Route 222 até Sunyshore City.']),
('platinum', 13, 'Sunyshore City', ARRAY['Em Sunyshore City, encontre Volkner no farol e fale com ele para que retorne ao ginásio.', 'Entre no ginásio e derrote Volkner, líder especialista no tipo Elétrico, para conquistar a Beacon Badge, depois fale com Jasmine na praia ao norte para receber Waterfall.', 'Use Surf e Waterfall pela Route 223 até a Pokémon League, depois atravesse a Victory Road e derrote os treinadores pelo caminho para chegar à entrada da Liga.']),
('platinum', 14, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Sinnoh que devem ser enfrentados em sequência, sendo Aaron especialista no tipo Inseto e Bertha especialista no tipo Terra.', 'Os próximos desafios são Flint, especialista no tipo Fogo, e Lucian, especialista no tipo Psíquico.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
('platinum', 15, 'Champion', ARRAY['Após vencer Lucian, enfrente a Champion da Liga Pokémon, Cynthia, que usa uma equipe de diferentes tipos e tem Garchomp como um de seus Pokémon.', 'A batalha contra a Champion acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, Cynthia acompanhará você até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.'])
), guias_sinnoh AS (
 SELECT versao, array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough
 FROM capitulos_sinnoh GROUP BY versao
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough
FROM public.pokemon AS jogo JOIN guias_sinnoh AS guia
  ON guia.versao = CASE WHEN jogo.slug = 'pokemon-platinum' THEN 'platinum' ELSE 'original' END
WHERE jogo.slug = 'pokemon-platinum'
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Cópia inicial de Platinum para Diamond e Pearl.
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT alvo.slug, origem.caps, origem.walkthrough
FROM public.detonados AS origem
JOIN public.pokemon AS alvo ON alvo.slug IN (
    'pokemon-diamond', 'pokemon-pearl',
    'pokemon-brilliant-diamond', 'pokemon-shining-pearl'
)
WHERE origem.slug = 'pokemon-platinum'
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Campanha de Pokémon Black e White.
WITH capitulos_unova (ordem, titulo, passos) AS (
VALUES
(1, 'Nuvema Town', ARRAY['A Professora Juniper apresenta o mundo Pokémon e pergunta seu nome, depois você começa sua jornada em Nuvema Town.', 'No seu quarto, encontre seus amigos Cheren e Bianca e abra o presente deixado pela professora para escolher entre Snivy, Tepig e Oshawott.', 'Após a escolha, enfrente Bianca e depois Cheren, então desça as escadas e fale com sua mãe para receber o Xtransceiver.', 'Vá ao laboratório da Professora Juniper para receber sua Pokédex, depois encontre seus amigos na saída ao norte da cidade e siga pela Route 1 até Accumula Town.']),
(2, 'Accumula Town', ARRAY['Em Accumula Town, acompanhe a Professora Juniper até o Pokémon Center e conheça os serviços disponíveis para sua jornada.', 'Do lado de fora, ouça o discurso de Ghetsis sobre a Team Plasma e enfrente N, um treinador que questiona a relação entre pessoas e Pokémon.', 'Saia de Accumula pelo oeste e siga pela Route 2, enfrentando Bianca perto da entrada de Striaton City.']),
(3, 'Striaton City', ARRAY['Em Striaton City, entre na escola de treinadores e enfrente Cheren, depois siga para o ginásio.', 'No ginásio, enfrente o líder que possui vantagem contra seu inicial, sendo Cilan especialista no tipo Planta, Chili no tipo Fogo ou Cress no tipo Água.', 'Após a vitória, receba a Trio Badge e acompanhe Fennel até sua casa para receber HM01 Cut.', 'Vá ao Dreamyard a leste da cidade, use Cut para abrir a passagem e derrote os membros da Team Plasma que estão incomodando Munna.', 'Volte à casa de Fennel para receber o C-Gear, depois saia de Striaton pelo norte e siga pela Route 3.', 'Na rota, enfrente Cheren e entre na Wellspring Cave para ajudar a recuperar o Pokémon roubado pela Team Plasma, depois continue até Nacrene City.']),
(4, 'Nacrene City', ARRAY['Ao chegar em Nacrene City, encontre Cheren e recupere sua equipe, depois siga até o museu da cidade e enfrente N.', 'Entre no museu e atravesse a biblioteca para chegar ao ginásio, onde você enfrentará Lenora, líder especialista no tipo Normal.', 'Após conquistar a Basic Badge, siga Lenora para fora do ginásio e descubra que a Team Plasma roubou um fóssil do museu.', 'Saia de Nacrene pelo oeste e ajude Burgh a procurar a equipe na Pinwheel Forest, derrotando seus membros até recuperar o fóssil.', 'Atravesse a Skyarrow Bridge para chegar a Castelia City.']),
(5, 'Castelia City', ARRAY['Em Castelia City, procure o ginásio e encontre Burgh, depois siga até o cais para descobrir que a Team Plasma roubou o Pokémon de Bianca.', 'Acompanhe Burgh e Iris até o prédio da equipe na rua do ginásio, derrote o membro que protege a entrada e entre para recuperar o Pokémon de Bianca.', 'Com o Pokémon devolvido, entre no ginásio e derrote Burgh, líder especialista no tipo Inseto, para conquistar a Insect Badge.', 'Saia de Castelia pelo norte e atravesse a Route 4, enfrentando Bianca e Cheren pelo caminho até chegar a Nimbasa City.']),
(6, 'Nimbasa City', ARRAY['Na entrada de Nimbasa City, ajude o dono da Pokémon Day Care contra os membros da Team Plasma e receba uma bicicleta.', 'Siga para o parque de diversões e encontre N perto da roda-gigante, depois enfrente-o para continuar sua jornada.', 'Entre no ginásio e percorra os trilhos da montanha-russa até encontrar Elesa, líder especialista no tipo Elétrico.', 'Após derrotá-la e receber a Bolt Badge, saia de Nimbasa pelo oeste, atravesse a Route 5 e a Driftveil Drawbridge até Driftveil City.']),
(7, 'Driftveil City', ARRAY['Ao chegar em Driftveil City, fale com Clay e siga para o Cold Storage ao sul, onde a Team Plasma está escondida.', 'Entre no frigorífico com Cheren e derrote os membros da equipe que estão dentro do contêiner, depois volte para a cidade.', 'Entre no ginásio e derrote Clay, líder especialista no tipo Terra, para conquistar a Quake Badge.', 'Saia de Driftveil pelo oeste, enfrente Bianca e siga pela Route 6 até a Chargestone Cave, onde Clay ajudará a liberar a entrada.', 'Atravesse a caverna, enfrente os membros da Team Plasma e vença a batalha contra N antes de seguir para Mistralton City.']),
(8, 'Mistralton City', ARRAY['Em Mistralton City, encontre Skyla e siga ao norte pela Route 7 até a Celestial Tower.', 'Suba a torre enfrentando os treinadores pelo caminho e toque o sino no último andar, depois volte a Mistralton.', 'Entre no ginásio e derrote Skyla, líder especialista no tipo Voador, para conquistar a Jet Badge.', 'Saia de Mistralton pelo norte, enfrente Cheren e receba HM03 Surf de Alder, depois atravesse a Twist Mountain até Icirrus City.']),
(9, 'Icirrus City', ARRAY['Em Icirrus City, entre no ginásio e atravesse os pisos de gelo até encontrar Brycen, líder especialista no tipo Gelo.', 'Derrote Brycen para receber a Freeze Badge, depois encontre Cheren e Bianca do lado de fora e siga ao norte até a Dragonspiral Tower.', 'Suba a torre enfrentando os membros da Team Plasma até encontrar N, que despertará o Pokémon lendário da sua versão.', 'Vá ao Relic Castle no Desert Resort e atravesse as ruínas para encontrar Alder, Cheren e Ghetsis.', 'Após sair do castelo, volte ao museu de Nacrene City e receba de Lenora a Light Stone em Black ou a Dark Stone em White.', 'Volte a Icirrus e siga pela Route 8 até a Tubeline Bridge, depois continue pela Route 9 até Opelucid City.']),
(10, 'Opelucid City', ARRAY['Em Opelucid City, ouça o discurso de Ghetsis e acompanhe Iris até a casa de Drayden para saber mais sobre os dragões lendários de Unova.', 'Entre no ginásio e abra caminho pelas estátuas de dragão até enfrentar Drayden em Black ou Iris em White, especialistas no tipo Dragão.', 'Após a vitória, receba a Legend Badge e encontre a Professora Juniper na saída da cidade para ganhar uma Master Ball.', 'Saia de Opelucid pelo leste e atravesse a Route 10, enfrentando Cheren pelo caminho, depois apresente suas oito insígnias aos guardas e entre na Victory Road.']),
(11, 'Victory Road', ARRAY['Atravesse a Victory Road enfrentando os treinadores e seguindo pelas passagens entre o interior e o exterior da montanha.', 'Ao encontrar a saída, siga para o norte até chegar à Liga Pokémon.']),
(12, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Unova que devem ser enfrentados antes da batalha final, sendo Shauntal especialista no tipo Fantasma e Grimsley especialista no tipo Sombrio.', 'Os próximos desafios são Caitlin, especialista no tipo Psíquico, e Marshal, especialista no tipo Lutador.', 'Os quatro podem ser enfrentados em qualquer ordem, então siga por uma das portas e derrote cada treinador para liberar o caminho seguinte.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(13, 'N Castle', ARRAY['Após vencer a Elite Four, examine a estátua no centro da sala e siga até o Champion Alder, onde você descobrirá que N chegou antes de você.', 'Entre no castelo que surge atrás da Liga Pokémon e avance enquanto os líderes de ginásio cuidam dos sábios da Team Plasma.', 'Durante a travessia, fale com Anthea em um dos quartos para recuperar sua equipe, depois continue até a sala do trono para encontrar N.', 'A pedra que você recebeu despertará Reshiram em Black ou Zekrom em White, então capture o Pokémon lendário antes de enfrentar N.', 'Após a batalha contra N, enfrente Ghetsis para encerrar os planos da Team Plasma.', 'Com Ghetsis derrotado, acompanhe a despedida de N e os créditos para concluir a campanha principal.'])
), guia_unova AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough
 FROM capitulos_unova
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough
FROM public.pokemon AS jogo CROSS JOIN guia_unova AS guia
WHERE jogo.slug IN ('pokemon-black', 'pokemon-white')
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Campanha de Pokémon Black 2 e White 2.
WITH capitulos_unova_2 (ordem, titulo, passos) AS (
VALUES
(1, 'Aspertia City', ARRAY['A Professora Juniper apresenta o mundo Pokémon, pergunta seu nome e apresenta seu amigo Hugh, depois você começa sua jornada em Aspertia City.', 'Saia de casa e siga com Hugh até o mirante ao norte da cidade, onde Bianca entregará sua Pokédex e permitirá que você escolha entre Snivy, Tepig e Oshawott.', 'Após escolher seu inicial, enfrente Hugh e acompanhe Bianca até o Pokémon Center, depois encontre sua mãe e a irmã de Hugh para receber os Running Shoes e os mapas de Unova.', 'Saia de Aspertia pelo norte e siga pela Route 19 até Floccesy Town, onde você encontrará Alder.', 'Continue pela Route 20 até o Floccesy Ranch, enfrente Hugh e ajude os donos da fazenda a encontrar o Herdier perdido.', 'Volte a Floccesy Town e visite a casa de Alder para enfrentar dois treinadores, depois retorne a Aspertia City para seu primeiro desafio de ginásio.', 'Na escola de treinadores, derrote Cheren, líder especialista no tipo Normal, para conquistar a Basic Badge.']),
(2, 'Virbank City', ARRAY['Saia de Aspertia pelo norte e atravesse a Route 20 em direção ao leste até chegar a Virbank City.', 'Entre no ginásio e derrote Roxie, líder especialista no tipo Veneno, para receber a Toxic Badge.', 'Após a vitória, visite o Pokéstar Studios ao norte da cidade e participe da gravação de um filme, depois siga até o porto de Virbank.', 'Ajude Roxie e Hugh a enfrentar a Team Plasma e receba HM01 Cut, depois persiga e derrote o membro da equipe que fugiu para a Route 20.', 'Volte ao porto e fale com o capitão para viajar de barco até Castelia City.']),
(3, 'Castelia City', ARRAY['Em Castelia City, encontre Iris e Hugh enquanto procuram a Team Plasma, depois siga com seu rival até o Castelia Sewers.', 'Atravesse os esgotos ao lado de Hugh e derrote os membros da Team Plasma, depois encontre Burgh e saia dos esgotos.', 'Entre no ginásio e derrote Burgh, líder especialista no tipo Inseto, para conquistar a Insect Badge.', 'Saia de Castelia pelo norte e atravesse a Route 4, enfrentando Colress pelo caminho.', 'Continue pelo deserto e atravesse a Join Avenue até chegar a Nimbasa City.']),
(4, 'Nimbasa City', ARRAY['Em Nimbasa City, siga até o parque de diversões e atravesse o antigo ginásio para encontrar a entrada do novo ginásio de Elesa.', 'Entre no ginásio e derrote Elesa, líder especialista no tipo Elétrico, para receber a Bolt Badge.', 'Após a vitória, ajude Hugh a enfrentar os membros da Team Plasma ao norte da cidade, depois siga pela saída oeste.', 'Atravesse a Route 5 e a Driftveil Drawbridge até chegar a Driftveil City.']),
(5, 'Driftveil City', ARRAY['Ao chegar em Driftveil City, encontre Rood e os antigos membros da Team Plasma, depois enfrente Rood e converse com Hugh.', 'Entre no ginásio e derrote Clay, líder especialista no tipo Terra, para conquistar a Quake Badge.', 'Após a vitória, siga ao sul da cidade e participe do Pokémon World Tournament, enfrentando Hugh, Cheren e Colress.', 'Ao sair do torneio, persiga o membro da Team Plasma até o navio e embarque com Hugh e Cheren.', 'Derrote os membros da equipe no Plasma Frigate, depois volte a Driftveil e saia pelo norte, seguindo pela Route 6.', 'Encontre Cheren pelo caminho e receba HM03 Surf, depois continue até a Chargestone Cave.']),
(6, 'Mistralton City', ARRAY['Atravesse a Chargestone Cave até chegar a Mistralton City, onde você encontrará a Professora Juniper e Skyla.', 'Siga pela Route 7 até a Celestial Tower e encontre a Professora Juniper, depois volte a Mistralton City.', 'Entre no ginásio e derrote Skyla, líder especialista no tipo Voador, para conquistar a Jet Badge.', 'Após a vitória, encontre Skyla no aeroporto e viaje de avião com ela, Juniper e Bianca até Lentimas Town.']),
(7, 'Undella Town', ARRAY['Em Lentimas Town, siga para leste e entre na Reversal Mountain, onde Bianca acompanhará você durante a travessia.', 'Atravesse a montanha enfrentando os treinadores pelo caminho até sair em Undella Town.', 'Em Undella, enfrente Hugh na saída norte da cidade, depois siga pela Route 13 até Lacunosa Town.', 'Em Lacunosa, junte-se a Hugh para enfrentar Zinzolin e um membro da Team Plasma, depois saia pelo oeste.', 'Atravesse a Route 12, a Village Bridge e a Route 11 até chegar a Opelucid City.']),
(8, 'Opelucid City', ARRAY['Em Opelucid City, entre no ginásio e derrote Drayden, líder especialista no tipo Dragão, para conquistar a Legend Badge.', 'Após a vitória, visite Drayden em sua casa e descubra mais sobre os dragões lendários de Unova, até que a Team Plasma ataque a cidade com o Plasma Frigate.', 'Enfrente os membros da equipe e derrote Zinzolin perto do ginásio, depois siga Drayden até a ponte ao sul para enfrentar a Shadow Triad.', 'Após os acontecimentos em Opelucid, voe para Undella Town e atravesse o Marine Tube até Humilau City.']),
(9, 'Humilau City', ARRAY['Em Humilau City, encontre Marlon e entre no ginásio, depois atravesse as passagens sobre a água até chegar ao líder.', 'Derrote Marlon, especialista no tipo Água, para conquistar a Wave Badge e completar suas oito insígnias.', 'Saia de Humilau pelo norte e siga pela Route 22 até encontrar Colress, que entregará a Colress Machine.', 'Volte à cidade e use Surf pela saída sul até a Seaside Cave, depois atravesse a caverna e use a Colress Machine no Crustle que bloqueia a passagem.', 'Ao sair da caverna, encontre Hugh e Marlon e embarque no Plasma Frigate.']),
(10, 'Plasma Frigate', ARRAY['Enfrente os membros da Team Plasma ao lado de Hugh e procure uma forma de desativar as barreiras que bloqueiam o navio.', 'Em Black 2, use os teletransportadores para encontrar os interruptores que desligam as barreiras.', 'Em White 2, obtenha o Plasma Card com um dos membros da equipe e descubra a senha para abrir a passagem.', 'Após atravessar as barreiras, enfrente Zinzolin e um membro da Team Plasma ao lado de Hugh, depois saia do navio quando a Shadow Triad retirar vocês de lá.', 'Volte a Humilau e siga pela Route 22 até a entrada do Giant Chasm.']),
(11, 'Giant Chasm', ARRAY['Encontre Hugh e os antigos membros da Team Plasma no Giant Chasm, depois atravesse a caverna até chegar à área onde o Plasma Frigate está estacionado.', 'Embarque novamente e enfrente os membros da equipe para desativar as barreiras do navio.', 'Desta vez, em Black 2 você precisará do Plasma Card e da senha, enquanto em White 2 deverá encontrar os interruptores pelos teletransportadores.', 'Após liberar a passagem, derrote Zinzolin e Colress, depois acompanhe Hugh no confronto com a Shadow Triad.', 'Saia do navio e siga até a caverna onde Ghetsis está com Kyurem, depois enfrente Black Kyurem em Black 2 ou White Kyurem em White 2.', 'Após derrotar Kyurem, enfrente Ghetsis para encerrar os planos da Team Plasma.', 'Volte à caverna do Giant Chasm e siga pela passagem que antes estava bloqueada, depois continue até a entrada da Victory Road.']),
(12, 'Victory Road', ARRAY['Atravesse a Victory Road enfrentando os treinadores e explorando as passagens entre a montanha e as ruínas.', 'Perto da saída, enfrente Hugh mais uma vez, depois continue até chegar à Liga Pokémon.']),
(13, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Unova que devem ser enfrentados antes da Champion, sendo Shauntal especialista no tipo Fantasma e Grimsley especialista no tipo Sombrio.', 'Os próximos desafios são Caitlin, especialista no tipo Psíquico, e Marshal, especialista no tipo Lutador.', 'Os quatro podem ser enfrentados em qualquer ordem, então siga por uma das portas e derrote cada treinador para liberar o caminho seguinte.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(14, 'Champion', ARRAY['Após vencer a Elite Four, examine a estátua no centro da sala e siga até a última sala para enfrentar Iris, a Champion da Liga Pokémon.', 'Iris é especialista no tipo Dragão, mas também usa Pokémon de outros tipos, incluindo Archeops, Aggron e Lapras.', 'A batalha contra a Champion acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, Iris acompanhará você até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.'])
), guia_unova_2 AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough
 FROM capitulos_unova_2
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough
FROM public.pokemon AS jogo CROSS JOIN guia_unova_2 AS guia
WHERE jogo.slug IN ('pokemon-black-2', 'pokemon-white-2')
ON CONFLICT (slug) DO UPDATE
SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough
WHERE public.detonados.walkthrough = '{}'::jsonb
  AND (cardinality(public.detonados.caps) = 0 OR public.detonados.caps = EXCLUDED.caps);

-- Campanha de Pokémon X e Y.
WITH capitulos_kalos (ordem, titulo, passos) AS (
VALUES
(1, 'Vaniville Town', ARRAY['O Professor Sycamore apresenta o mundo Pokémon e pede que você escolha sua aparência e seu nome antes de começar sua jornada em Kalos.', 'Ao sair de casa, você conhece Shauna e Calem ou Serena, que convidam você para encontrá-los em Aquacorde Town.', 'Siga pela Route 1 até Aquacorde Town e encontre seus novos amigos, onde Tierno entregará seu primeiro Pokémon e você poderá escolher entre Chespin, Fennekin e Froakie.', 'Depois de receber a Pokédex e uma carta para sua mãe, enfrente Shauna e volte para Vaniville Town para entregar a carta antes de partir em sua aventura.']),
(2, 'Santalune City', ARRAY['Siga para o norte pela Route 2, onde Calem ou Serena ensinará como capturar Pokémon, depois continue até entrar na Santalune Forest.', 'Atravesse a floresta com a ajuda de Shauna e siga pela Route 3 até chegar a Santalune City, onde está o primeiro ginásio de Kalos.', 'Dentro do ginásio, passe pela teia e enfrente os treinadores até encontrar Viola, líder especialista no tipo Inseto.', 'Derrote Viola para conquistar sua primeira insígnia, a Bug Badge, depois saia da cidade pelo norte e siga pela Route 4 em direção a Lumiose City.']),
(3, 'Lumiose City', ARRAY['Na entrada de Lumiose City, encontre Sina e Dexio e acompanhe-os até o laboratório do Professor Sycamore.', 'Suba até encontrar o professor e enfrente-o em uma batalha, depois escolha entre Bulbasaur, Charmander e Squirtle para receber um Pokémon que iniciou sua jornada em Kanto.', 'Depois de conversar com seus amigos e conhecer Lysandre, saia de Lumiose City pela passagem oeste e siga pela Route 5 até Camphrier Town.']),
(4, 'Camphrier Town', ARRAY['Ao chegar a Camphrier Town, visite o Shabboneau Castle e siga para a Route 7, onde encontrará um Snorlax dormindo e bloqueando a passagem.', 'Para acordá-lo, siga ao norte pela Route 6 até o Parfum Palace e ajude a procurar o Furfrou que escapou para os jardins do palácio.', 'Depois de encontrar o Pokémon e assistir à apresentação de fogos de artifício, receba a Poké Flute e volte para o Snorlax na Route 7.', 'Use a Poké Flute para acordá-lo, capture-o ou derrote-o e continue pela rota, passando pelo Pokémon Day Care e enfrentando Tierno e Trevor ao lado de Calem ou Serena.', 'Siga pela Connecting Cave e pela Route 8 até Ambrette Town, visite o laboratório de fósseis e depois atravesse a Route 9 montado em um Rhyhorn para chegar à Glittering Cave.', 'Dentro da caverna, enfrente os membros da Team Flare e encontre o pesquisador do laboratório, que permitirá escolher entre o Jaw Fossil e o Sail Fossil.', 'Volte para Ambrette Town e passe pelo aquário para chegar à praia da Route 8, depois siga pela costa até Cyllage City.']),
(5, 'Cyllage City', ARRAY['Ao explorar Cyllage City, encontre Grant próximo à subida da Route 10 e receba o HM04 Strength.', 'Vá ao ginásio e escale as paredes, enfrentando os treinadores pelo caminho até chegar a Grant, líder especialista no tipo Pedra.', 'Derrote Grant para conquistar sua segunda insígnia, a Cliff Badge, depois saia da cidade pela Route 10.', 'Atravesse a rota das pedras e passe por Geosenge Town, onde encontrará membros da Team Flare, depois siga pela Route 11 e enfrente Korrina e seus dois Lucario.', 'Continue pela Reflection Cave até chegar a Shalour City.']),
(6, 'Shalour City', ARRAY['Ao chegar a Shalour City, visite a Tower of Mastery e converse com Korrina e seu avô sobre a Mega Evolução.', 'Enfrente Calem ou Serena para decidir quem ficará com a Mega Ring, depois siga para o ginásio da cidade.', 'Dentro do ginásio, percorra a pista de patinação e derrote os treinadores até encontrar Korrina, líder especialista no tipo Lutador.', 'Depois de conquistar sua terceira insígnia, a Rumble Badge, volte ao topo da Tower of Mastery para receber a Mega Ring e aprender a usar a Mega Evolução em uma batalha com Lucario.', 'Ao deixar Shalour City pela Route 12, receba o HM03 Surf de Calem ou Serena e continue pela rota até chegar a Coumarine City.']),
(7, 'Coumarine City', ARRAY['Ao chegar a Coumarine City, encontre o Professor Sycamore próximo ao monotrilho e receba o HM02 Fly.', 'Pegue o monotrilho até a parte alta da cidade e enfrente Calem ou Serena diante do ginásio antes de entrar.', 'Dentro do ginásio, suba pelas plantas e enfrente os treinadores até chegar a Ramos, líder especialista no tipo Planta.', 'Derrote Ramos para conquistar sua quarta insígnia, a Plant Badge, depois siga para o sul pela Route 13.', 'Atravesse a área desértica até encontrar um membro da Team Flare, derrote-o e procure o Power Plant Pass perto de uma pedra para entrar na Kalos Power Plant.', 'Dentro da usina, enfrente os membros da Team Flare e derrote seus líderes para restaurar a energia de Lumiose City, depois continue pela Route 13 até retornar à cidade.']),
(8, 'Lumiose Gym', ARRAY['De volta a Lumiose City, siga para a Prism Tower, localizada no centro da cidade, e entre no ginásio.', 'Responda às perguntas e enfrente os treinadores para subir os andares da torre até encontrar Clemont, líder especialista no tipo Elétrico.', 'Derrote Clemont para conquistar sua quinta insígnia, a Voltage Badge, depois siga para a Route 14.', 'Atravesse a rota e continue pelo caminho até chegar a Laverre City.']),
(9, 'Laverre City', ARRAY['Em Laverre City, entre no ginásio e use os teletransportadores para avançar pelas salas até encontrar Valerie, líder especialista no tipo Fada.', 'Derrote Valerie para conquistar sua sexta insígnia, a Fairy Badge, depois siga para a Poké Ball Factory ao norte da cidade.', 'Dentro da fábrica, enfrente os membros da Team Flare e ajude o presidente, depois receba a Master Ball como recompensa.', 'Saia de Laverre pela Route 15 e continue pela Route 16 até chegar a Dendemille Town.']),
(10, 'Anistar City', ARRAY['Em Dendemille Town, siga para o norte até a Frost Cavern, onde a Team Flare está causando problemas para os Pokémon da caverna.', 'Atravesse a caverna e derrote os membros da Team Flare que estão incomodando Abomasnow, depois volte para Dendemille Town e siga pela Route 17.', 'Atravesse a rota coberta de neve montado em Mamoswine e continue até chegar a Anistar City.', 'Enfrente Calem ou Serena e siga para o ginásio, onde os caminhos levam até Olympia, líder especialista no tipo Psíquico.', 'Derrote Olympia para conquistar sua sétima insígnia, a Psychic Badge, depois saia do ginásio e receba uma mensagem de Lysandre sobre os planos da Team Flare.']),
(11, 'Geosenge Town', ARRAY['Volte para Lumiose City e entre no Lysandre Café, onde membros da Team Flare estão disfarçados, depois examine a estante para encontrar a passagem até o Lysandre Labs.', 'Enfrente Lysandre e avance pelo laboratório, derrotando os membros da Team Flare e usando os painéis para encontrar o caminho pelos andares.', 'Depois de enfrentar Xerosic e descobrir mais sobre a arma da Team Flare, siga para Geosenge Town e procure a entrada da base secreta ao noroeste da cidade.', 'Dentro da base, enfrente Lysandre e avance com a ajuda de seus amigos até encontrar o Pokémon lendário usado para fornecer energia à arma.', 'Em Pokémon X, você encontrará Xerneas, enquanto em Pokémon Y encontrará Yveltal, então enfrente o lendário e tente capturá-lo.', 'Depois da batalha, enfrente Lysandre mais uma vez e impeça os planos da Team Flare, depois volte para Anistar City e siga ao sul pela Route 18.']),
(12, 'Snowbelle City', ARRAY['Atravesse a Route 18 até Couriway Town e enfrente o Professor Sycamore, depois siga pela Route 19 para encontrar seus amigos e receber o HM05 Waterfall de Shauna.', 'Continue até Snowbelle City e visite o ginásio, onde descobrirá que o líder está ausente.', 'Siga ao sul pela Route 20 e atravesse a floresta até o Pokémon Village, onde encontrará Wulfric.', 'Converse com ele e volte para o ginásio de Snowbelle City, depois gire as plataformas e avance pelo gelo até encontrar o líder especialista no tipo Gelo.', 'Derrote Wulfric para conquistar sua oitava e última insígnia, a Iceberg Badge, depois saia da cidade pela Route 21 em direção à Victory Road.']),
(13, 'Victory Road', ARRAY['Atravesse a Route 21 e siga até a entrada da Victory Road, onde suas oito insígnias permitirão continuar em direção à Liga Pokémon.', 'Passe pelas cavernas e pelos caminhos ao ar livre, usando os golpes necessários para superar os obstáculos e enfrentando os treinadores pelo caminho.', 'Depois de enfrentar Calem ou Serena mais uma vez, continue até sair da Victory Road e chegar à Pokémon League.']),
(14, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Kalos que devem ser enfrentados em sequência, sendo Malva especialista no tipo Fogo, Siebold no tipo Água, Wikstrom no tipo Aço e Drasna no tipo Dragão.', 'Os quatro treinadores podem ser enfrentados em qualquer ordem, então escolha uma das salas e continue até derrotar todos.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(15, 'Champion', ARRAY['Depois de vencer a Elite Four, siga até a sala da Champion e enfrente Diantha, que usa uma equipe variada e pode megaevoluir seu Gardevoir.', 'Ao vencer a batalha, registre sua equipe no Hall da Fama e volte para Lumiose City, onde seus amigos e o Professor Sycamore celebram sua conquista.', 'Durante a celebração, enfrente AZ e acompanhe o reencontro dele com Floette, encerrando sua jornada principal em Kalos.'])
), guia_kalos AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough FROM capitulos_kalos
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough FROM public.pokemon AS jogo CROSS JOIN guia_kalos AS guia
WHERE jogo.slug IN ('pokemon-x', 'pokemon-y')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough;

-- Campanha de Pokémon Sun e Moon.
WITH capitulos_alola (ordem, titulo, passos) AS (
VALUES
(1, 'Iki Town', ARRAY['O Professor Kukui apresenta o mundo Pokémon e pede que você escolha sua aparência e seu nome antes de começar sua jornada em Alola.', 'Depois de chegar à sua nova casa na Melemele Island, acompanhe Kukui até Iki Town para conhecer o kahuna da ilha.', 'Siga ao norte até a Mahalo Trail e encontre Lillie, depois tente proteger o pequeno Cosmog de um grupo de Spearow e seja salvo por Tapu Koko.', 'Volte a Iki Town e conheça Hala, que permitirá escolher seu primeiro Pokémon entre Rowlet, Litten e Popplio.', 'No caminho de volta para casa, conheça Hau e enfrente-o em sua primeira batalha, depois apresente seu novo Pokémon à sua mãe.', 'No dia seguinte, siga com Kukui até o festival de Iki Town e enfrente Hau novamente, depois receba de Hala o Z-Ring e conheça o desafio das ilhas de Alola.']),
(2, 'Hau’oli City', ARRAY['Acompanhe Lillie até o laboratório do Professor Kukui e receba a Rotom Pokédex, depois siga até a escola de treinadores.', 'Enfrente os alunos espalhados pela escola e, após vencer a professora, continue até Hau’oli City com Lillie.', 'Explore a cidade e encontre Hau, depois enfrente os membros da Team Skull perto do porto e vença Ilima, o capitão responsável pelo primeiro desafio.', 'Saia de Hau’oli City pela Route 2 e continue até a entrada da Verdant Cavern.']),
(3, 'Verdant Cavern', ARRAY['Entre na Verdant Cavern e converse com Ilima para começar seu primeiro desafio.', 'Procure os Pokémon escondidos nas tocas da caverna e enfrente-os, depois passe pelos membros da Team Skull e continue até a parte mais profunda.', 'Enfrente o Totem Gumshoos em Pokémon Sun ou o Totem Alolan Raticate em Pokémon Moon, lembrando que o Pokémon dominante pode chamar aliados durante a batalha.', 'Após a vitória, receba o Normalium Z e saia da caverna, depois siga pela Route 3 até a Melemele Meadow para encontrar Lillie.', 'Procure Nebby entre as flores, volte para encontrar Hau e enfrente-o, depois retorne a Iki Town para o grande desafio da ilha.']),
(4, 'Iki Town - Grand Trial', ARRAY['Em Iki Town, enfrente Hala, o kahuna da Melemele Island e especialista no tipo Lutador.', 'Depois da vitória, receba o Fightinium Z e complete o grande desafio da ilha, depois receba acesso ao Tauros Charge para quebrar pedras pelo caminho.', 'Volte ao laboratório de Kukui e siga com Lillie até o porto de Hau’oli City, onde você e Hau embarcarão com o Professor Kukui para a Akala Island.']),
(5, 'Heahea City', ARRAY['Ao chegar a Heahea City, conheça Olivia, a kahuna da Akala Island, e Mallow, uma das capitãs responsáveis pelos desafios da ilha.', 'Siga para a Route 4 e continue até Paniola Town, onde Hau desafiará você para uma batalha.', 'Depois de vencê-lo, siga para o Paniola Ranch e encontre Mallow, que ajudará você a registrar o Stoutland Search para procurar itens escondidos.', 'Continue pela Route 5, enfrente Gladion pelo caminho e siga até a Brooklet Hill para encontrar Lana.']),
(6, 'Brooklet Hill', ARRAY['Converse com Lana e comece seu desafio, depois use Lapras para atravessar a água e investigar as ondulações.', 'Continue seguindo Lana pelos lagos até encontrar o Totem Wishiwashi, depois derrote-o e seus aliados para completar o desafio.', 'Receba o Waterium Z e a Fishing Rod, depois volte ao caminho onde os Sudowoodo bloqueavam a passagem.', 'Siga para a Royal Avenue e entre no Battle Royal Dome, onde você participará de uma batalha com Hau, Gladion e o Masked Royal.', 'Após a batalha, conheça Kiawe e siga para o Wela Volcano Park.']),
(7, 'Wela Volcano Park', ARRAY['Suba o vulcão até encontrar Kiawe e começar seu desafio, depois observe as danças dos Marowak e identifique as diferenças entre as apresentações.', 'Enfrente os Pokémon e treinadores que aparecerem durante o desafio, depois derrote a Totem Salazzle para receber o Firium Z.', 'Kiawe também registrará o Charizard Glide, permitindo viajar rapidamente para lugares que você já visitou.', 'Saia do vulcão e continue pela Route 8 até encontrar a entrada da Lush Jungle.']),
(8, 'Lush Jungle', ARRAY['Converse com Mallow e procure os quatro ingredientes escondidos pela floresta, usando o Stoutland Search para ajudar na busca.', 'Depois de encontrar tudo, volte para Mallow e ajude na preparação que atrairá o Totem Lurantis.', 'Derrote Lurantis e seus aliados para completar o desafio e receber o Grassium Z, depois encontre o Professor Kukui.', 'Siga para o Dimensional Research Lab em Heahea City e converse com a Professora Burnet, depois encontre Lillie e continue até a Route 9.', 'Atravesse o Diglett’s Tunnel com a ajuda de Hau para enfrentar a Team Skull, depois siga pela Route 9 até Konikoni City.']),
(9, 'Konikoni City', ARRAY['Em Konikoni City, procure Olivia em sua loja e receba uma mensagem indicando que ela está nas Ruins of Life.', 'Siga pelo Memorial Hill e pelo Akala Outskirts, enfrentando os membros da Team Skull pelo caminho, depois encontre Olivia diante das ruínas.', 'Enfrente Olivia, a kahuna da Akala Island e especialista no tipo Pedra, para completar o grande desafio e receber o Rockium Z.', 'Depois da vitória, encontre Faba e viaje com Hau até o Aether Paradise.']),
(10, 'Aether Paradise', ARRAY['No Aether Paradise, conheça Wicke e Lusamine enquanto visita as instalações da Aether Foundation.', 'Quando uma criatura misteriosa surgir por uma abertura, enfrente-a e depois siga com Hau até o barco para viajar à Ula’ula Island.']),
(11, 'Malie City', ARRAY['Ao chegar a Malie City, enfrente Hau e procure o Professor Kukui no Malie Garden.', 'Depois de conversar com o professor e encontrar Lillie, saia pela Route 10 e derrote os membros da Team Skull perto do ponto de ônibus.', 'Pegue o ônibus até o Mount Hokulani e enfrente Molayne diante do observatório, depois entre no prédio para encontrar Sophocles.']),
(12, 'Hokulani Observatory', ARRAY['Converse com Sophocles para começar seu desafio e responda às perguntas sobre os sons que ouvir, enfrentando os Pokémon que aparecerem pelo caminho.', 'Ao final, derrote o Totem Vikavolt para receber o Electrium Z, depois pegue a máscara esquecida pelo Professor Kukui e volte ao Malie Garden.', 'No jardim, encontre Kukui e enfrente Guzma, o líder da Team Skull, depois saia de Malie City pela Route 11.', 'Continue pelas Routes 12 e 13, usando o Mudsdale recebido de Hapu para atravessar o terreno rochoso, até chegar à Tapu Village.', 'Siga pela Route 14 até o Thrifty Megamart e encontre Acerola para seu próximo desafio.']),
(13, 'Thrifty Megamart', ARRAY['Entre no mercado abandonado e use a câmera para procurar os Pokémon Fantasma escondidos entre os objetos.', 'Depois de fotografar os Pokémon pelo caminho, encontre e enfrente o Totem Mimikyu para completar o desafio de Acerola e receber o Ghostium Z.', 'Volte à Tapu Village e siga pela Route 15 até a Aether House, onde encontrará Acerola e as crianças que vivem no local.', 'Depois de enfrentar os membros da Team Skull e descobrir que um Pokémon foi levado, siga pela Route 15 e use Sharpedo para atravessar as pedras no mar.', 'Continue pela Route 16 e pela Ula’ula Meadow até chegar à Route 17 e à entrada de Po Town.']),
(14, 'Po Town', ARRAY['Entre em Po Town e atravesse a cidade ocupada pela Team Skull, enfrentando seus membros e passando pelos obstáculos até chegar à Shady House.', 'Dentro da mansão, procure as senhas e avance pelas salas até encontrar Guzma.', 'Derrote o líder da Team Skull e recupere o Yungoos que havia sido levado, depois volte à Aether House.', 'Ao chegar, descubra que Lillie e Nebby foram levados, depois enfrente Gladion e siga com ele até o porto de Malie City.', 'Antes de partir, enfrente Nanu, o kahuna da Ula’ula Island e especialista no tipo Sombrio, para completar o grande desafio e receber o Darkinium Z.', 'Depois da vitória, viaje com Gladion e Hau até o Aether Paradise.']),
(15, 'Aether Paradise - Resgate', ARRAY['Ao retornar ao Aether Paradise, enfrente os funcionários da Aether Foundation e avance com Hau e Gladion pelos andares da instalação.', 'Derrote Faba e continue até a área onde a Team Skull está reunida, depois enfrente Guzma para chegar até Lillie e Lusamine.', 'Lusamine usa o poder de Nebby para abrir Ultra Wormholes, então enfrente-a enquanto seus amigos tentam ajudar Lillie e Cosmog.', 'Depois da batalha, Lusamine e Guzma entram na abertura, enquanto Nebby assume uma nova forma.', 'Descanse nas instalações e encontre Lillie e Gladion no dia seguinte, depois receba a Master Ball e viaje de barco até a Poni Island.']),
(16, 'Seafolk Village', ARRAY['Ao chegar à Seafolk Village, siga com Lillie pela Poni Wilds até encontrar Hapu na Ancient Poni Path.', 'Receba o Machamp Shove da avó de Hapu e siga para as Ruins of Hope, usando Machamp para empurrar as pedras que bloqueiam a passagem.', 'Encontre Hapu nas ruínas e veja sua nomeação como kahuna da Poni Island, depois volte à Seafolk Village e viaje com Lillie até a Exeggutor Island.', 'Encontre a outra flauta na ilha e volte para Poni, depois siga para o Vast Poni Canyon.', 'Antes de atravessar o canyon, enfrente Hapu, especialista no tipo Terra, para completar o grande desafio da Poni Island e receber o Groundium Z.']),
(17, 'Vast Poni Canyon', ARRAY['Atravesse o Vast Poni Canyon com Lillie, usando as montarias para superar os obstáculos e enfrentando os treinadores pelo caminho.', 'Perto do fim do canyon, entre na área do último desafio e avance até o pedestal para enfrentar o Totem Kommo-o.', 'Depois da vitória, receba o Dragonium Z e continue até o altar no fim do caminho.']),
(18, 'Altar', ARRAY['No altar, toque as duas flautas com Lillie para ajudar Nebby, que se transformará em Solgaleo em Pokémon Sun ou Lunala em Pokémon Moon.', 'Viaje com Lillie pelo Ultra Wormhole até o Ultra Space e encontre Lusamine, depois enfrente sua equipe para ajudá-la.', 'Após a batalha, volte ao altar e converse com o Pokémon lendário, então enfrente-o e tente capturá-lo antes de continuar sua jornada.', 'Depois de voltar, siga para a Ula’ula Island e vá até Tapu Village para chegar ao Mount Lanakila.']),
(19, 'Mount Lanakila', ARRAY['Na entrada do Mount Lanakila, enfrente Gladion mais uma vez e depois suba a montanha em direção à Liga Pokémon.', 'Atravesse as cavernas e use o elevador para alcançar o topo, onde o Professor Kukui espera para apresentar a recém-construída Pokémon League.', 'Prepare sua equipe no Pokémon Center antes de entrar na Liga.']),
(20, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Alola que devem ser enfrentados em sequência, sendo Hala especialista no tipo Lutador, Olivia no tipo Pedra, Acerola no tipo Fantasma e Kahili no tipo Voador.', 'Os quatro treinadores podem ser enfrentados em qualquer ordem, então escolha uma das salas e continue até derrotar todos.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(21, 'Champion', ARRAY['Depois de derrotar a Elite Four, siga até a sala do Champion e sente-se no trono, onde o Professor Kukui aparecerá para seu último desafio.', 'Enfrente Kukui e sua equipe variada para conquistar o título de primeiro Champion da Liga Pokémon de Alola.', 'Após a vitória, sua equipe será registrada no Hall da Fama e seus amigos celebrarão a conquista na Melemele Island, encerrando a campanha principal.'])
), guia_alola AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough FROM capitulos_alola
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough FROM public.pokemon AS jogo CROSS JOIN guia_alola AS guia
WHERE jogo.slug IN ('pokemon-sun', 'pokemon-moon')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough;

-- Campanha de Pokémon Ultra Sun e Ultra Moon.
WITH capitulos_ultra (ordem, titulo, passos) AS (
VALUES
(1, 'Iki Town', ARRAY['O Professor Kukui apresenta o mundo Pokémon e pede que você escolha sua aparência e seu nome antes de começar sua jornada em Alola.', 'Depois de chegar à sua nova casa na Melemele Island, saia pela Route 1 e encontre o Professor Kukui, que permitirá escolher seu primeiro Pokémon entre Rowlet, Litten e Popplio.', 'Continue em direção a Iki Town e conheça Hau, depois enfrente-o em sua primeira batalha antes de entrar na cidade.', 'Siga ao norte até a Mahalo Trail e encontre Lillie, depois tente proteger o pequeno Cosmog de um grupo de Spearow e seja salvo por Tapu Koko.', 'Volte a Iki Town com Lillie e conheça Hala, o kahuna da ilha, depois retorne para casa e apresente seu Pokémon à sua mãe.', 'No dia seguinte, siga até o festival de Iki Town e enfrente Hau novamente, depois receba seu Z-Power Ring e conheça o desafio das ilhas de Alola.']),
(2, 'Hau’oli City', ARRAY['Acompanhe Lillie até o laboratório do Professor Kukui e receba a Rotom Pokédex, depois siga até a escola de treinadores.', 'Enfrente os alunos espalhados pela escola e, após vencer a professora, continue até Hau’oli City com Lillie.', 'Explore a cidade e encontre Hau, depois enfrente os membros da Team Skull e conheça Ilima, o capitão responsável pelo primeiro desafio.', 'Saia de Hau’oli City pela Route 2 e continue até a entrada da Verdant Cavern.']),
(3, 'Verdant Cavern', ARRAY['Entre na Verdant Cavern e converse com Ilima para começar seu primeiro desafio.', 'Procure os Pokémon escondidos nas tocas da caverna e enfrente-os, depois passe pelos membros da Team Skull e continue até a parte mais profunda.', 'Enfrente o Totem Gumshoos em Pokémon Ultra Sun ou o Totem Alolan Raticate em Pokémon Ultra Moon, lembrando que o Pokémon dominante pode chamar aliados durante a batalha.', 'Após a vitória, receba o Normalium Z e siga pela Route 3 até a Melemele Meadow para encontrar Lillie e procurar Nebby.', 'Depois de encontrar Nebby e enfrentar Hau, volte a Iki Town para o grande desafio da ilha.']),
(4, 'Iki Town - Grand Trial', ARRAY['Em Iki Town, enfrente Hala, o kahuna da Melemele Island e especialista no tipo Lutador.', 'Depois da vitória, receba o Fightinium Z e complete o grande desafio da ilha, além de receber acesso ao Tauros Charge para quebrar pedras pelo caminho.', 'Volte para Hau’oli City e siga até o porto para viajar com Hau e o Professor Kukui até a Akala Island.']),
(5, 'Heahea City', ARRAY['Ao chegar à Akala Island, conheça Olivia, a kahuna da ilha, e Mallow, uma das capitãs responsáveis pelos desafios.', 'Siga pela Route 4 até Paniola Town e enfrente Hau, depois continue até o Paniola Ranch e encontre Mallow.', 'Receba acesso ao Stoutland Search para procurar itens escondidos e siga pela Route 5, onde Gladion desafiará você para uma batalha.', 'Depois de vencê-lo, continue até a Brooklet Hill para encontrar Lana.']),
(6, 'Brooklet Hill', ARRAY['Converse com Lana e comece seu desafio, depois use Lapras para atravessar a água e investigar os Pokémon nos lagos.', 'Continue acompanhando Lana até encontrar o Totem Araquanid, depois derrote-o e seus aliados para completar o desafio.', 'Receba o Waterium Z e a Fishing Rod, depois siga em direção à Royal Avenue.', 'Entre no Battle Royal Dome e participe de uma batalha com Hau, Gladion e o Masked Royal, depois conheça Kiawe e siga para o Wela Volcano Park.']),
(7, 'Wela Volcano Park', ARRAY['Suba o vulcão até encontrar Kiawe e começar seu desafio, depois observe as danças dos Marowak e identifique as diferenças entre as apresentações.', 'Enfrente os Pokémon e treinadores que aparecerem durante o desafio, depois derrote o Totem Alolan Marowak para receber o Firium Z.', 'Kiawe também registrará o Charizard Glide, permitindo viajar rapidamente para lugares que você já visitou.', 'Saia do vulcão e continue pela Route 8 até encontrar a entrada da Lush Jungle.']),
(8, 'Lush Jungle', ARRAY['Converse com Mallow e procure os ingredientes necessários para seu desafio, explorando a floresta e enfrentando os Pokémon que aparecerem.', 'Depois de encontrar os ingredientes, volte para Mallow e ajude na preparação que atrairá o Totem Lurantis.', 'Derrote Lurantis e seus aliados para completar o desafio e receber o Grassium Z, depois encontre o Professor Kukui.', 'Siga para o Dimensional Research Lab em Heahea City e converse com a Professora Burnet, depois continue até o Diglett’s Tunnel.', 'Atravesse o túnel, enfrente os membros da Team Skull com a ajuda de Hau e siga pela Route 9 até Konikoni City.']),
(9, 'Konikoni City', ARRAY['Em Konikoni City, procure Olivia em sua loja e siga para as Ruins of Life.', 'Passe pelo Memorial Hill e pelo Akala Outskirts, enfrentando os membros da Team Skull pelo caminho, depois encontre Olivia diante das ruínas.', 'Enfrente Olivia, a kahuna da Akala Island e especialista no tipo Pedra, para completar o grande desafio e receber o Rockium Z.', 'Depois da vitória, encontre Faba e viaje com Hau até o Aether Paradise.']),
(10, 'Aether Paradise', ARRAY['No Aether Paradise, conheça Wicke e Lusamine enquanto visita as instalações da Aether Foundation.', 'Quando uma criatura misteriosa surgir por uma abertura, enfrente-a e conheça membros da Ultra Recon Squad, que estão investigando os acontecimentos ligados às Ultra Beasts.', 'Depois da visita, siga com Hau até o barco para viajar à Ula’ula Island.']),
(11, 'Malie City', ARRAY['Ao chegar a Malie City, enfrente Hau e procure o Professor Kukui no Malie Garden.', 'Depois de conversar com o professor e encontrar Lillie, saia pela Route 10 e enfrente os membros da Team Skull perto do ponto de ônibus.', 'Pegue o ônibus até o Mount Hokulani e enfrente Molayne diante do observatório, depois entre no prédio para encontrar Sophocles.']),
(12, 'Hokulani Observatory', ARRAY['Converse com Sophocles para começar seu desafio e ajude a conduzir os Charjabug pelo observatório para alimentar o equipamento.', 'Depois de resolver os desafios, enfrente o Totem Togedemaru e seus aliados para receber o Electrium Z.', 'Volte ao Malie Garden, encontre o Professor Kukui e enfrente Guzma, o líder da Team Skull, depois saia de Malie City em direção à Route 11.', 'Continue pelas Routes 12 e 13, usando o Mudsdale recebido de Hapu para atravessar o terreno rochoso, até chegar à Tapu Village.', 'Siga até a Aether House pela Route 15 e conheça Acerola, depois vá para a Route 14 e entre no Thrifty Megamart.']),
(13, 'Thrifty Megamart', ARRAY['Entre no mercado abandonado e use a câmera para procurar os Pokémon Fantasma escondidos entre os objetos.', 'Depois de fotografar os Pokémon pelo caminho, encontre e enfrente o Totem Mimikyu para completar o desafio de Acerola e receber o Ghostium Z.', 'Volte à Aether House e enfrente os membros da Team Skull, depois siga pela Route 15 e use Sharpedo para atravessar as pedras no mar.', 'Continue pela Route 16 e pela Ula’ula Meadow até chegar à Route 17 e à entrada de Po Town.']),
(14, 'Po Town', ARRAY['Entre em Po Town e atravesse a cidade ocupada pela Team Skull, enfrentando seus membros e passando pelos obstáculos até chegar à Shady House.', 'Dentro da mansão, procure as senhas e avance pelas salas até encontrar Guzma.', 'Derrote o líder da Team Skull e recupere o Yungoos que havia sido levado, depois volte à Aether House.', 'Ao chegar, descubra que Lillie e Nebby foram levados, depois enfrente Gladion e siga com ele até o porto de Malie City.', 'Antes de partir, enfrente Nanu, o kahuna da Ula’ula Island e especialista no tipo Sombrio, para completar o grande desafio e receber o Darkinium Z.', 'Depois da vitória, viaje com Gladion e Hau até o Aether Paradise.']),
(15, 'Aether Paradise - Resgate', ARRAY['Ao retornar ao Aether Paradise, enfrente os funcionários da Aether Foundation e avance com Hau e Gladion pelos andares da instalação.', 'Derrote Faba e continue até a área onde a Team Skull está reunida, depois enfrente Guzma para chegar até Lillie e Lusamine.', 'Enfrente Lusamine e descubra que ela pretende viajar pelo Ultra Wormhole para encontrar Necrozma, uma ameaça que a Ultra Recon Squad está tentando deter.', 'Depois que Lusamine e Guzma partirem, descanse nas instalações e encontre Lillie e Gladion no dia seguinte.', 'Receba a Master Ball e uma das flautas necessárias para chegar ao lendário de Alola, depois viaje de barco até a Poni Island.']),
(16, 'Seafolk Village', ARRAY['Ao chegar à Seafolk Village, siga com Lillie pela Poni Wilds até encontrar Hapu na Ancient Poni Path.', 'Receba o Machamp Shove da avó de Hapu e siga para as Ruins of Hope, usando Machamp para empurrar as pedras que bloqueiam a passagem.', 'Encontre Hapu nas ruínas e veja sua nomeação como kahuna da Poni Island, depois volte à Seafolk Village e viaje com Lillie até a Exeggutor Island.', 'Encontre a outra flauta na ilha e volte para Poni, depois siga para o Vast Poni Canyon.']),
(17, 'Vast Poni Canyon', ARRAY['Antes de entrar no canyon, enfrente o membro da Ultra Recon Squad que aparecer pelo caminho, depois avance com Lillie pela caverna.', 'Use as montarias para superar os obstáculos e enfrente os treinadores até chegar à área de um desafio sem capitão.', 'Avance até o pedestal e enfrente o Totem Kommo-o, depois receba o Dragonium Z e continue até o altar no fim do caminho.']),
(18, 'Altar', ARRAY['No altar, toque as duas flautas com Lillie para ajudar Nebby, que se transformará em Solgaleo em Pokémon Ultra Sun ou Lunala em Pokémon Ultra Moon.', 'Quando um Ultra Wormhole se abrir, Lusamine e Guzma retornarão feridos e Necrozma aparecerá para tomar o poder do lendário.', 'Enfrente Necrozma após sua fusão com Solgaleo em Ultra Sun ou Lunala em Ultra Moon, depois da batalha ele fugirá levando a luz de Alola.', 'Com a ajuda da Ultra Recon Squad, viaje pelo Ultra Wormhole até a Ultra Megalopolis para detê-lo.']),
(19, 'Ultra Megalopolis', ARRAY['Atravesse a Ultra Megalopolis e suba até encontrar Necrozma, que assumirá sua forma Ultra Necrozma.', 'Enfrente-o para devolver a luz de Alola, lembrando que essa é uma batalha contra um Pokémon muito poderoso e que ele não pode ser capturado nesse momento.', 'Depois da vitória, converse com a Ultra Recon Squad e volte para Alola, onde você poderá continuar seu desafio das ilhas.']),
(20, 'Seafolk Village - Mina', ARRAY['Volte à Seafolk Village e entre no barco onde Mina vive para começar seu desafio, depois enfrente a capitã e receba a primeira pétala.', 'Visite os outros capitães pelas ilhas para reunir as pétalas restantes, encontrando Ilima no Hau’oli Cemetery, Mallow ou Lana na Lush Jungle, Kiawe no Wela Volcano Park e Sophocles no Hokulani Observatory.', 'Por fim, vá até a Aether House para encontrar Nanu e receber a pétala que falta, depois volte para Mina na Seafolk Village.', 'Com todas as pétalas reunidas, enfrente o Totem Ribombee e seus aliados para completar o desafio e receber o Fairium Z.']),
(21, 'Exeggutor Island', ARRAY['Depois de completar o desafio de Mina, viaje até a Exeggutor Island e encontre Hapu para o último grande desafio das ilhas.', 'Enfrente Hapu, a kahuna da Poni Island e especialista no tipo Terra, para completar seu desafio e receber o Groundium Z.', 'Após a vitória, siga para a Ula’ula Island e vá até Tapu Village para chegar ao Mount Lanakila.']),
(22, 'Mount Lanakila', ARRAY['Na entrada do Mount Lanakila, enfrente Gladion mais uma vez e depois suba a montanha em direção à Liga Pokémon.', 'Atravesse as cavernas e continue até o topo, onde o Professor Kukui espera para apresentar a recém-construída Pokémon League.', 'Prepare sua equipe no Pokémon Center antes de entrar na Liga.']),
(23, 'Elite Four', ARRAY['A Elite Four reúne quatro dos melhores treinadores de Alola que devem ser enfrentados em sequência, sendo Molayne especialista no tipo Aço, Olivia no tipo Pedra, Acerola no tipo Fantasma e Kahili no tipo Voador.', 'Os quatro treinadores podem ser enfrentados em qualquer ordem, então escolha uma das salas e continue até derrotar todos.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(24, 'Champion', ARRAY['Depois de derrotar a Elite Four, siga até a sala do Champion e prepare-se para seu último desafio, pois Hau chegará para disputar o título com você.', 'Enfrente Hau e sua equipe para conquistar o título de primeiro Champion da Liga Pokémon de Alola.', 'Após a vitória, comemore com seus amigos a conclusão da jornada e sua conquista como Champion.'])
), guia_ultra AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough FROM capitulos_ultra
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough FROM public.pokemon AS jogo CROSS JOIN guia_ultra AS guia
WHERE jogo.slug IN ('pokemon-ultra-sun', 'pokemon-ultra-moon')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough;

-- Campanha de Pokémon Sword e Shield.
WITH capitulos_galar (ordem, titulo, passos) AS (
VALUES
(1, 'Postwick', ARRAY['Depois de escolher sua aparência e seu nome, comece sua jornada em Postwick e encontre Hop, seu vizinho e amigo.', 'Siga com ele até Wedgehurst para receber Leon, o Champion de Galar e irmão mais velho de Hop, depois volte à casa de Hop para escolher seu primeiro Pokémon entre Grookey, Scorbunny e Sobble.', 'Enfrente Hop em sua primeira batalha e, no dia seguinte, entre com ele na Slumbering Weald para procurar um Wooloo que fugiu.', 'Avance pela floresta até encontrar um Pokémon misterioso, depois volte para Postwick com Leon e siga pela Route 1 até Wedgehurst.']),
(2, 'Wedgehurst', ARRAY['Em Wedgehurst, visite o laboratório e conheça Sonia, que entregará sua Pokédex.', 'Siga pela Route 2 até a casa da Professora Magnolia e enfrente Hop diante da casa, depois receba de Leon a recomendação para participar do Gym Challenge.', 'Após encontrar uma Wishing Star, receba de Magnolia a Dynamax Band, que permitirá usar o Dynamax durante batalhas em locais apropriados.', 'Volte à estação de Wedgehurst e viaje de trem com Hop em direção a Motostoke.']),
(3, 'Motostoke', ARRAY['Quando o trem parar antes do destino, atravesse a Wild Area em direção ao norte até chegar a Motostoke.', 'Na cidade, encontre Sonia e siga para o estádio, onde você fará sua inscrição para o Gym Challenge e escolherá o número do seu uniforme.', 'Vá ao hotel para descansar e enfrente os membros da Team Yell que estão causando confusão na recepção, depois conheça Marnie, outra participante do desafio.', 'No dia seguinte, participe da cerimônia de abertura no estádio e saia de Motostoke pela Route 3.', 'Atravesse a rota e a Galar Mine, enfrente Bede pelo caminho e continue pela Route 4 até chegar a Turffield.']),
(4, 'Turffield', ARRAY['Em Turffield, encontre Sonia e descubra mais sobre a história de Galar antes de seguir para o estádio.', 'Dentro do ginásio, conduza os Wooloo pelos caminhos e evite os obstáculos até alcançar Milo, líder especialista no tipo Planta.', 'Derrote Milo para conquistar sua primeira insígnia, a Grass Badge, depois saia da cidade pela Route 5.', 'Atravesse a rota e ajude um homem que está sendo incomodado pela Team Yell para receber a Rotom Bike, depois enfrente Hop na ponte e continue até Hulbury.']),
(5, 'Hulbury', ARRAY['Ao chegar a Hulbury, encontre Nessa e siga até o estádio para seu próximo desafio.', 'Dentro do ginásio, acione os interruptores para controlar as correntes de água e abrir caminho até Nessa, líder especialista no tipo Água.', 'Derrote Nessa para conquistar sua segunda insígnia, a Water Badge, depois encontre o Chairman Rose no restaurante da cidade.', 'Saia de Hulbury pela Galar Mine No. 2, enfrente Bede e ajude Hop contra a Team Yell, depois continue até Motostoke.']),
(6, 'Motostoke Gym', ARRAY['Ao voltar a Motostoke, encontre Marnie e enfrente-a antes de participar do próximo desafio.', 'Dentro do ginásio, capture ou derrote os Pokémon para acumular os pontos necessários, depois avance até Kabu, líder especialista no tipo Fogo.', 'Derrote Kabu para conquistar sua terceira insígnia, a Fire Badge, depois siga com Hop para a Wild Area.', 'Atravesse a parte norte da Wild Area e continue até Hammerlocke.']),
(7, 'Hammerlocke', ARRAY['Em Hammerlocke, encontre o Chairman Rose e visite o estádio para conhecer mais sobre a energia utilizada em Galar.', 'Depois de conversar com Sonia sobre a história da região, saia da cidade pela Route 6.', 'Enfrente os membros da Team Yell que bloqueiam a passagem e continue pela rota até chegar a Stow-on-Side.']),
(8, 'Stow-on-Side', ARRAY['Ao chegar a Stow-on-Side, encontre Hop e enfrente-o antes de seguir para o estádio.', 'Dentro do ginásio, conduza o carrinho pelos obstáculos até alcançar o líder da sua versão.', 'Em Pokémon Sword, enfrente Bea, especialista no tipo Lutador, enquanto em Pokémon Shield você enfrentará Allister, especialista no tipo Fantasma.', 'Depois da vitória, conquiste sua quarta insígnia e siga até o mural da cidade, onde Bede está causando uma confusão.', 'Após os acontecimentos no mural, encontre Sonia e continue pela Glimwood Tangle até chegar a Ballonlea.']),
(9, 'Ballonlea', ARRAY['Em Ballonlea, entre no ginásio e responda às perguntas durante as batalhas para avançar até Opal.', 'Derrote Opal, líder especialista no tipo Fada, para conquistar sua quinta insígnia, a Fairy Badge.', 'Depois da vitória, volte a Hammerlocke e encontre Hop e Bede, depois siga pela saída leste da cidade.', 'Atravesse a Route 7 e a Route 8, enfrentando os treinadores pelo caminho, depois continue pela área coberta de neve até Circhester.']),
(10, 'Circhester', ARRAY['Em Circhester, siga até o estádio e use o equipamento entregue na entrada para encontrar o caminho seguro pelos pisos.', 'Em Pokémon Sword, enfrente Gordie, líder especialista no tipo Pedra, enquanto em Pokémon Shield você enfrentará Melony, especialista no tipo Gelo.', 'Depois da vitória, conquiste sua sexta insígnia e encontre Sonia para conversar sobre as descobertas relacionadas aos heróis de Galar.', 'Enfrente Hop perto da saída da cidade e siga para o sul pela Route 9.', 'Ajude novamente o homem que está sendo incomodado pela Team Yell e receba a melhoria que permite usar a Rotom Bike sobre a água, depois atravesse a rota até chegar a Spikemuth.']),
(11, 'Spikemuth', ARRAY['Na entrada de Spikemuth, encontre Marnie e enfrente-a para conseguir entrar na cidade.', 'Atravesse as ruas enfrentando os membros da Team Yell até encontrar Piers, líder especialista no tipo Sombrio.', 'Derrote Piers para conquistar sua sétima insígnia, a Dark Badge, depois saia de Spikemuth e volte para Hammerlocke.']),
(12, 'Hammerlocke Gym', ARRAY['Ao retornar a Hammerlocke, encontre Leon e Sonia para descobrir mais sobre os acontecimentos envolvendo a energia de Galar.', 'Entre no estádio e enfrente os treinadores em batalhas em dupla até encontrar Raihan, líder especialista no tipo Dragão.', 'Derrote Raihan para conquistar sua oitava e última insígnia, a Dragon Badge, depois siga com Hop até a estação.', 'Viaje de trem para Wyndon e atravesse a Route 10, enfrentando os treinadores pelo caminho até chegar à cidade onde acontece a Champion Cup.']),
(13, 'Wyndon', ARRAY['Em Wyndon, siga até o estádio e inscreva-se na Champion Cup, onde os vencedores do Gym Challenge disputam a chance de enfrentar Leon.', 'Nas semifinais, enfrente Marnie e depois Hop para garantir sua vaga na próxima etapa.', 'Após as batalhas, procure Leon com a ajuda de Hop, Marnie e Piers, depois siga até a Rose Tower.', 'Enfrente os funcionários da Macro Cosmos e suba a torre até encontrar Oleana, depois derrote-a e encontre Leon e o Chairman Rose.']),
(14, 'Champion Cup', ARRAY['Volte ao estádio para as finais da Champion Cup e enfrente Bede, que interromperá o início das disputas.', 'Em seguida, enfrente Nessa e depois Bea em Pokémon Sword ou Allister em Pokémon Shield, antes de enfrentar Raihan na última batalha do torneio.', 'Depois de vencer as finais e conquistar o direito de enfrentar Leon, uma transmissão do Chairman Rose interromperá a preparação para a batalha.']),
(15, 'Slumbering Weald', ARRAY['Volte com Hop para Postwick e entre novamente na Slumbering Weald para procurar uma forma de ajudar Leon.', 'Atravesse a floresta até encontrar a Rusted Sword e o Rusted Shield, depois leve os objetos com você e siga para Hammerlocke.']),
(16, 'Darkest Day', ARRAY['Em Hammerlocke, entre no estádio e siga até a área subterrânea para encontrar o Chairman Rose.', 'Derrote Rose e suba até o topo do estádio para ajudar Leon, depois enfrente Eternatus.', 'Após a primeira batalha, enfrente sua forma Eternamax ao lado de Hop, Zacian e Zamazenta, usando a ajuda dos lendários para superar o poder de Eternatus.', 'Depois da vitória, capture Eternatus e volte a Wyndon para a batalha final da Champion Cup.']),
(17, 'Champion', ARRAY['No estádio de Wyndon, enfrente Leon, o Champion de Galar, e sua equipe variada para disputar o título.', 'Prepare-se para enfrentar seu Charizard, que pode assumir a forma Gigantamax durante a batalha.', 'Depois de vencer Leon, torne-se o novo Champion de Galar e celebre sua conquista, encerrando a campanha principal.'])
), guia_galar AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough FROM capitulos_galar
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough FROM public.pokemon AS jogo CROSS JOIN guia_galar AS guia
WHERE jogo.slug IN ('pokemon-sword', 'pokemon-shield')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough;

-- Campanha de Pokémon Scarlet e Violet.
WITH capitulos_paldea (ordem, titulo, passos) AS (
VALUES
(1, 'Cabo Poco', ARRAY['Depois de escolher sua aparência e seu nome, comece sua jornada em Cabo Poco e encontre o Diretor Clavell diante de sua casa.', 'Acompanhe Clavell até a casa de Nemona e escolha seu primeiro Pokémon entre Sprigatito, Fuecoco e Quaxly, depois enfrente sua nova amiga em uma batalha.', 'Siga pela Poco Path e encontre um Pokémon misterioso na praia, sendo Koraidon em Pokémon Scarlet ou Miraidon em Pokémon Violet.', 'Ajude o Pokémon e atravesse a caverna ao lado dele, depois encontre Arven perto do farol e enfrente-o antes de seguir para Los Platos.', 'Continue em direção a Mesagoza e enfrente Nemona, que apresentará a Terastalização durante a batalha.']),
(2, 'Mesagoza', ARRAY['Entre em Mesagoza e siga até a Naranja Academy em Pokémon Scarlet ou a Uva Academy em Pokémon Violet.', 'No caminho para a escola, ajude Penny contra os membros da Team Star e receba uma ligação de Cassiopeia.', 'Dentro da academia, conheça seus colegas e converse com Nemona, Arven e o Diretor Clavell, depois descanse em seu quarto.', 'No dia seguinte, participe do início da Treasure Hunt e prepare-se para explorar Paldea.', 'Saia de Mesagoza pelo portão oeste e siga até Cortondo para seu primeiro desafio.']),
(3, 'Cortondo', ARRAY['Em Cortondo, inscreva-se no ginásio e participe do teste que consiste em conduzir uma grande azeitona até o fim do percurso.', 'Depois de completar o teste, enfrente Katy, líder especialista no tipo Inseto, para conquistar sua primeira insígnia.', 'Volte em direção a Mesagoza e siga para a South Province Area Three, onde Arven indicará o primeiro Titã.']),
(4, 'Stony Cliff Titan', ARRAY['Na South Province Area Three, procure Klawf nas regiões rochosas e aproxime-se para começar a batalha.', 'Depois que o Titã fugir e comer uma Herba Mystica, encontre-o novamente e enfrente-o ao lado de Arven.', 'Após a vitória, acompanhe Arven até a caverna e encontre a primeira Herba Mystica, depois compartilhe o sanduíche com Koraidon ou Miraidon.', 'Com suas forças parcialmente recuperadas, o lendário aprenderá a correr mais rápido, então siga para Artazon.']),
(5, 'Artazon', ARRAY['Em Artazon, inscreva-se no ginásio e procure os Sunflora escondidos pela cidade para completar o teste.', 'Volte ao ginásio e enfrente Brassius, líder especialista no tipo Planta, para conquistar sua segunda insígnia.', 'Depois da vitória, siga para a West Province Area One e procure o Titã que vive na montanha.']),
(6, 'Open Sky Titan', ARRAY['Suba a montanha desviando das pedras que caem pelo caminho até encontrar Bombirdier, o Open Sky Titan.', 'Enfrente o Titã e persiga-o após sua fuga, depois lute novamente ao lado de Arven para encontrar a próxima Herba Mystica.', 'Compartilhe o sanduíche com Koraidon ou Miraidon para recuperar mais uma habilidade, permitindo que ele atravesse a água.', 'Continue pela West Province Area One até encontrar a base da Team Star.']),
(7, 'Team Star - Dark Crew', ARRAY['Na entrada da base, converse com Clive e enfrente o membro da Team Star que protege o portão.', 'Entre na base e use seus Pokémon para derrotar os Pokémon da equipe dentro do tempo, depois enfrente Giacomo, chefe especialista no tipo Sombrio.', 'Após a vitória, receba sua recompensa e siga para Levincia, na parte leste de Paldea.']),
(8, 'Levincia', ARRAY['Em Levincia, inscreva-se no ginásio e participe da transmissão de Iono, procurando o Diretor Clavell nas imagens mostradas durante o teste.', 'Depois de encontrá-lo e vencer os treinadores do desafio, enfrente Iono, líder especialista no tipo Elétrico.', 'Derrote Iono para conquistar sua terceira insígnia, depois siga para a East Province Area One e procure a próxima base da Team Star.']),
(9, 'Team Star - Fire Crew', ARRAY['Entre na base e use seus Pokémon para derrotar os membros da equipe e seus Pokémon dentro do tempo.', 'Depois de completar o desafio, enfrente Mela, chefe especialista no tipo Fogo, para vencer a segunda base da Team Star.', 'Após a vitória, siga para a East Province Area Three e procure o Titã que vive na região.']),
(10, 'Lurking Steel Titan', ARRAY['Na East Province Area Three, procure Orthworm e aproxime-se para começar a batalha contra o Lurking Steel Titan.', 'Depois que ele fugir e encontrar a Herba Mystica, persiga-o e enfrente-o novamente ao lado de Arven.', 'Após a vitória, encontre a erva com Arven e compartilhe o sanduíche com Koraidon ou Miraidon para permitir que o lendário salte mais alto.', 'Siga para Cascarrafa, a oeste de Paldea.']),
(11, 'Cascarrafa', ARRAY['Em Cascarrafa, inscreva-se no ginásio e procure Kofu, que saiu em direção a Porto Marinada sem sua carteira.', 'Atravesse o Asado Desert até Porto Marinada, entregue a carteira e participe do leilão para conseguir o ingrediente desejado por Kofu.', 'Volte a Cascarrafa e enfrente Kofu, líder especialista no tipo Água, para conquistar sua quarta insígnia.', 'Depois da vitória, siga até Tagtree Thicket e procure a base da Team Star escondida na floresta.']),
(12, 'Team Star - Poison Crew', ARRAY['Entre na base e use seus Pokémon para derrotar os Pokémon da equipe dentro do tempo.', 'Depois de completar o desafio, enfrente Atticus, chefe especialista no tipo Veneno, para vencer a terceira base da Team Star.', 'Siga para Medali, na West Province Area Three, para continuar o Gym Challenge.']),
(13, 'Medali', ARRAY['Em Medali, inscreva-se no ginásio e procure pistas com os outros participantes para descobrir o prato secreto do Treasure Eatery.', 'Peça o prato correto no restaurante e enfrente Larry, líder especialista no tipo Normal.', 'Depois de conquistar sua quinta insígnia, siga para a montanha ao norte até chegar a Montenevera.']),
(14, 'Montenevera', ARRAY['Em Montenevera, inscreva-se no ginásio e participe das batalhas em dupla diante do público para completar o teste.', 'Depois de vencer os treinadores, enfrente Ryme, líder especialista no tipo Fantasma, também em uma batalha em dupla.', 'Derrote Ryme para conquistar sua sexta insígnia, depois siga para o Asado Desert em busca do próximo Titã.']),
(15, 'Quaking Earth Titan', ARRAY['No Asado Desert, procure o Quaking Earth Titan e aproxime-se para começar a batalha.', 'Em Pokémon Scarlet, você enfrentará Great Tusk, enquanto em Pokémon Violet encontrará Iron Treads.', 'Depois que o Titã fugir, persiga-o e enfrente-o novamente ao lado de Arven, depois encontre a Herba Mystica na caverna.', 'Compartilhe o sanduíche com Koraidon ou Miraidon para permitir que ele plane pelo ar, depois siga para Alfornada.']),
(16, 'Alfornada', ARRAY['Atravesse a Alfornada Cavern até chegar à cidade e inscreva-se no ginásio.', 'Participe do treinamento de expressão emocional e enfrente os treinadores para completar o teste, depois desafie Tulip.', 'Derrote Tulip, líder especialista no tipo Psíquico, para conquistar sua sétima insígnia.', 'Depois da vitória, siga para o Glaseado Mountain e encontre o ginásio da região.']),
(17, 'Glaseado Gym', ARRAY['No Glaseado Gym, inscreva-se para o desafio e deslize pela montanha com Koraidon ou Miraidon, passando pelos portões antes que o tempo acabe.', 'Depois de completar o percurso, enfrente Grusha, líder especialista no tipo Gelo.', 'Derrote Grusha para conquistar sua oitava e última insígnia, depois siga para a North Province em busca da próxima base da Team Star.']),
(18, 'Team Star - Fairy Crew', ARRAY['Na North Province Area Three, encontre a base da equipe especialista no tipo Fada e enfrente o membro que protege a entrada.', 'Entre na base e derrote os Pokémon da equipe dentro do tempo, depois enfrente Ortega para conquistar mais uma vitória contra a Team Star.', 'Após a batalha, siga para o Casseroya Lake em busca do último Titã.']),
(19, 'False Dragon Titan', ARRAY['No Casseroya Lake, procure a pequena ilha onde há vários Tatsugiri e encontre o Pokémon responsável pelo aparecimento do Titã.', 'Enfrente Dondozo e acompanhe-o após sua fuga, depois lute novamente ao lado de Arven e prepare-se para enfrentar Tatsugiri.', 'Depois da vitória, encontre a última Herba Mystica e descubra mais sobre o motivo de Arven estar procurando as ervas.', 'Compartilhe o sanduíche com Koraidon ou Miraidon para recuperar a habilidade de escalar, depois siga para a última base da Team Star.']),
(20, 'Team Star - Fighting Crew', ARRAY['Na North Province Area Two, encontre a última base da Team Star e enfrente os membros que protegem a entrada.', 'Entre na base e use seus Pokémon para completar o desafio dentro do tempo, depois enfrente Eri, chefe especialista no tipo Lutador.', 'Após derrotar Eri, Cassiopeia pedirá que você volte à academia para concluir a operação.']),
(21, 'Path of Legends', ARRAY['Depois de encontrar as cinco Herba Mystica, volte ao laboratório perto do farol da Poco Path para encontrar Arven e Mabosstiff.', 'Converse com Arven e enfrente sua equipe em uma batalha para concluir a jornada em busca das ervas.', 'Depois da batalha, Arven receberá uma mensagem sobre a Area Zero, mas antes disso ainda é necessário concluir os outros caminhos da Treasure Hunt.']),
(22, 'Starfall Street', ARRAY['Volte à academia em Mesagoza e encontre Clive diante da entrada, depois descubra sua identidade e enfrente-o em uma batalha.', 'Entre na escola e vá ao pátio durante a noite para encontrar Cassiopeia, cuja identidade será revelada.', 'Enfrente Cassiopeia e sua equipe para concluir a história da Team Star.']),
(23, 'Elite Four', ARRAY['Com as oito insígnias em mãos, siga para a Pokémon League, ao norte de Mesagoza, e passe pela entrevista para começar o desafio.', 'A Elite Four reúne quatro dos melhores treinadores de Paldea que devem ser enfrentados em sequência, sendo Rika especialista no tipo Terra, Poppy no tipo Aço, Larry no tipo Voador e Hassel no tipo Dragão.', 'Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas.']),
(24, 'Champion', ARRAY['Depois de vencer a Elite Four, enfrente Geeta, a Top Champion de Paldea, para conquistar a classificação de Champion.', 'Após a vitória, encontre Nemona e siga até a praça de Mesagoza para enfrentá-la em uma última batalha da Victory Road.', 'Derrote Nemona para concluir o desafio dos ginásios e a jornada de vocês como rivais.']),
(25, 'Area Zero', ARRAY['Depois de concluir a Victory Road, a Path of Legends e a Starfall Street, encontre Arven, Nemona e Penny na Zero Gate para seguir até a Area Zero.', 'Desça pelo interior da cratera com seus amigos e visite as quatro estações de pesquisa, enfrentando os Pokémon encontrados pelo caminho e desativando as travas do laboratório.', 'Ao chegar ao Zero Lab, encontre a Professora Sada em Pokémon Scarlet ou o Professor Turo em Pokémon Violet e descubra a verdade sobre as pesquisas realizadas na Area Zero.', 'Enfrente a equipe do professor e, depois, use Koraidon em Pokémon Scarlet ou Miraidon em Pokémon Violet para superar o último desafio.', 'Após a batalha, volte com seus amigos e acompanhe o encerramento da Treasure Hunt, concluindo a campanha principal de Paldea.'])
), guia_paldea AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS walkthrough FROM capitulos_paldea
)
INSERT INTO public.detonados (slug, caps, walkthrough)
SELECT jogo.slug, guia.caps, guia.walkthrough FROM public.pokemon AS jogo CROSS JOIN guia_paldea AS guia
WHERE jogo.slug IN ('pokemon-scarlet', 'pokemon-violet')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, walkthrough = EXCLUDED.walkthrough;

-- Ajustes da campanha de Pokémon Yellow.
UPDATE public.detonados SET walkthrough = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(walkthrough, ARRAY['Pallet Town'], to_jsonb(ARRAY['O Professor Carvalho apresenta o mundo Pokémon, pergunta seu nome e pede que você escolha o nome do seu rival.', 'Ao sair de casa, siga até a grama ao norte para encontrar o Professor Carvalho, que capturará um Pikachu selvagem e levará você ao laboratório.', 'Seu rival pegará o Eevee que estava sobre a mesa, então receba Pikachu do professor e enfrente seu rival em sua primeira batalha.', 'Com seu primeiro Pokémon, siga para o norte pela Route 1 até Viridian City, enfrentando Pokémon selvagens pelo caminho para ganhar experiência.', 'Em Viridian City, entre no Poké Mart, receba a encomenda do atendente e volte a Pallet Town para entregá-la ao Professor Carvalho e receber sua Pokédex.']), true), ARRAY['Cerulean City'], to_jsonb(ARRAY['Atravesse a Route 3 e entre na caverna Mt. Moon, onde você encontrará treinadores e membros da Team Rocket.', 'Antes de sair da caverna, enfrente o Super Nerd e escolha entre o Dome Fossil e o Helix Fossil, que mais tarde poderão ser revividos como Pokémon dos tipos Água e Pedra.', 'Depois de escolher o fóssil, enfrente Jessie e James antes de continuar até a saída da caverna.', 'Ao sair da caverna, siga para a direita pela Route 4 até chegar a Cerulean City.', 'Visite a casa ao lado do Pokémon Center e converse com a garota para receber um Bulbasaur, caso seu Pikachu esteja feliz com você.', 'Saia de Cerulean pelo norte, enfrente seu rival e os treinadores da ponte, depois siga para leste até encontrar a casa de Bill.', 'Depois de atravessar a ponte, converse com o treinador ao norte da Route 24 para receber um Charmander.', 'Converse com Bill, que está na forma de um Pokémon, e use o computador para ajudá-lo a voltar ao normal e receber o S.S. Ticket.', 'Volte a Cerulean City, derrote Misty para conquistar sua segunda insígnia e siga pela casa ao norte do ginásio, onde antes havia um policial.']), true), ARRAY['Vermilion City'], to_jsonb(ARRAY['Passe pela casa roubada em Cerulean e siga ao sul pela Route 5, onde fica o Pokémon Day Care, depois entre na casa ao sudeste para atravessar a passagem subterrânea até a Route 6 e continuar para Vermilion City.', 'No porto ao sul da cidade, apresente o S.S. Ticket para embarcar na S.S. Anne, suba até encontrar seu rival e, depois de vencê-lo, fale com o capitão para receber HM01 Cut.', 'Ao deixar o navio, a S.S. Anne partirá do porto, então ensine Cut a um Pokémon compatível e use o golpe na árvore diante do ginásio.', 'Dentro do ginásio, encontre o primeiro interruptor nos cestos e procure o segundo em um cesto vizinho, depois derrote o líder Lt. Surge para receber sua terceira insígnia, a Thunder Badge.', 'Após a vitória, fale com a policial no centro de Vermilion City para receber um Squirtle.']), true), ARRAY['Celadon City'], to_jsonb(ARRAY['(DICA) Para iluminar o Rock Tunnel, siga para leste de Vermilion e atravesse a Diglett’s Cave até a Route 2, onde você poderá usar Cut e falar com o ajudante do Professor Carvalho para receber HM05 Flash após registrar dez espécies capturadas na Pokédex.', 'Volte a Cerulean City e siga para leste, usando Cut na árvore que bloqueia a passagem, depois atravesse as Routes 9 e 10 até encontrar um Pokémon Center ao lado da entrada do Rock Tunnel.', 'Atravesse o Rock Tunnel e siga para Lavender Town, depois vá para oeste pela Route 8 e use a passagem subterrânea até a Route 7 para chegar a Celadon City.', 'No Game Corner, derrote o membro da Team Rocket diante do pôster e examine-o para abrir o esconderijo, depois encontre a Lift Key e use o elevador para chegar ao andar onde Giovanni está.', 'Enfrente Jessie e James diante da sala de Giovanni, depois derrote o líder da Team Rocket e receba o Silph Scope.', 'Ao sul de Celadon, use Cut para chegar ao ginásio e derrote Erika, líder do tipo Planta, para conquistar sua quarta insígnia, a Rainbow Badge.', 'Suba o Celadon Mall até o terraço e compre uma bebida em uma das máquinas, para entregá-la a um guarda quando for acessar Saffron City.']), true), ARRAY['Fuchsia City'], to_jsonb(ARRAY['Em Lavender Town, entre na Pokémon Tower com o Silph Scope e suba até enfrentar o espírito de Marowak, um Pokémon do tipo Terra que bloqueia a passagem.', 'Depois da batalha, continue até o último andar e derrote Jessie e James, depois fale com Mr. Fuji, que levará você à casa dele e entregará a Poké Flute.', 'Siga ao sul de Lavender pela Route 12, use a Poké Flute para acordar o Snorlax que bloqueia o caminho e continue pelas Routes 13, 14 e 15 até Fuchsia City.', 'Ao norte de Fuchsia, entre na Safari Zone e atravesse as áreas até encontrar a Secret House para receber HM03 Surf, aproveitando para pegar os Gold Teeth no caminho.', 'Entregue os Gold Teeth ao guarda na casa ao sul de Fuchsia para receber HM04 Strength, depois enfrente Koga, líder do tipo Veneno, para conquistar sua quinta insígnia, a Soul Badge.', 'Depois da vitória, volte a Lavender pelo mesmo caminho para seguir em direção a Saffron City.']), true), ARRAY['Saffron City'], to_jsonb(ARRAY['Entregue a bebida comprada no Celadon Mall a qualquer um dos guardas de Saffron City para liberar o acesso à cidade.', 'Ao norte de Saffron, visite o Fighting Dojo ao lado do ginásio e derrote os treinadores para escolher entre os Pokémon do tipo Lutador Hitmonlee e Hitmonchan.', 'Entre na Silph Co., o grande prédio no centro da cidade, enfrente a Team Rocket e encontre o Card Key no quinto andar para abrir as salas trancadas.', 'No terceiro andar, use o teletransportador de uma das salas trancadas para avançar pela empresa e enfrentar seu rival, depois continue até encontrar Jessie e James.', 'Derrote a dupla e siga até Giovanni, o líder da Team Rocket.', 'Após derrotar Giovanni, fale com o presidente da Silph Co. para receber a Master Ball e siga para o ginásio, onde poderá enfrentar Sabrina, líder do tipo Psíquico, pela Marsh Badge.']), true), ARRAY['Champion'], to_jsonb(ARRAY['Após vencer Lance, enfrente o campeão de Kanto, seu rival, que chegou à Liga antes de você e possui uma equipe que inclui uma evolução de seu Eevee.', 'A batalha contra o campeão acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, o Professor Carvalho parabenizará você e o acompanhará até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.']), true) WHERE slug = 'pokemon-yellow';

-- Ajustes da campanha de Pokémon Let’s Go.
UPDATE public.detonados SET walkthrough = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(walkthrough, ARRAY['Champion'], to_jsonb(ARRAY['Após vencer Lance, enfrente o campeão de Kanto, seu rival, que chegou à Liga antes de você.', 'A batalha contra o campeão acontece em seguida à Elite Four, então use os itens de recuperação que tiver disponíveis antes de entrar na sala.', 'Após a vitória, o Professor Carvalho parabenizará você e o acompanhará até o Hall of Fame, onde sua equipe será registrada e a campanha principal chegará ao fim.']), true), ARRAY['Pallet Town'], to_jsonb(ARRAY['O Professor Carvalho apresenta o mundo Pokémon, pergunta seu nome e pede que você escolha o nome do seu rival.', 'Ao sair de casa, siga até a grama ao norte para encontrar o professor, depois capture Pikachu em Let’s Go, Pikachu! ou Eevee em Let’s Go, Eevee!.', 'Acompanhe o professor até o laboratório e receba seu parceiro e a Pokédex, depois siga pela Route 1 até Viridian City.', 'Em Viridian City, entre no Poké Mart, receba a encomenda do atendente e volte a Pallet Town para entregá-la ao Professor Carvalho.', 'Depois de entregar a encomenda, enfrente seu rival, que usa Eevee em Let’s Go, Pikachu! ou Pikachu em Let’s Go, Eevee!.']), true), ARRAY['Pewter City'], to_jsonb(ARRAY['Depois de receber sua Pokédex, volte a Viridian City e siga ao norte pela Route 2 até a entrada da Viridian Forest.', 'Atravesse a floresta, enfrentando treinadores e Pokémon selvagens pelo caminho, e continue para o norte até chegar a Pewter City.', 'Na cidade, recupere sua equipe no Pokémon Center e apresente um Pokémon do tipo Planta ou Água na entrada do ginásio para poder enfrentar Brock.', 'Após a vitória, receba a primeira insígnia e a TM01 Headbutt.', 'Com a insígnia em mãos, saia de Pewter pelo leste e siga pela Route 3 em direção a Cerulean City.']), true), ARRAY['Celadon City'], to_jsonb(ARRAY['Para iluminar o Rock Tunnel, siga para leste de Vermilion e atravesse a Diglett’s Cave até a Route 2, depois encontre o ajudante do Professor Carvalho para ensinar a técnica secreta Light Up ao seu parceiro.', 'Volte a Cerulean City e siga para leste, usando Chop Down na árvore que bloqueia a passagem, depois atravesse as Routes 9 e 10 até encontrar um Pokémon Center ao lado da entrada do Rock Tunnel.', 'Ao chegar a Lavender Town, entre na Pokémon Tower e avance até encontrar o fantasma que bloqueia o caminho, depois saia da torre e veja Jessie e James levando Cubone.', 'Siga para Celadon City pela Route 8 e pela passagem subterrânea, depois encontre Brock na cidade para receber o Tea.', 'No Game Corner, derrote o membro da Team Rocket diante do pôster e examine-o para abrir o esconderijo.', 'Dentro da base, ajude seu parceiro a alcançar a Lift Key pelo duto de ventilação, depois use o elevador e enfrente Jessie, James e Archer antes de chegar a Giovanni.', 'Derrote Giovanni para receber o Silph Scope e libertar Cubone.', 'Ao sul de Celadon, use Chop Down para chegar ao ginásio e apresente seu Pikachu ou Eevee na entrada, depois derrote Erika para conquistar a Rainbow Badge.']), true), ARRAY['Fuchsia City'], to_jsonb(ARRAY['Volte a Lavender Town e entre na Pokémon Tower com o Silph Scope, depois suba até descobrir que o fantasma é a mãe de Cubone.', 'Depois da despedida de Cubone e Marowak, continue até o último andar e derrote Jessie e James, depois fale com Mr. Fuji para receber a Poké Flute.', 'Siga ao sul de Lavender pela Route 12, use a Poké Flute para acordar o Snorlax que bloqueia o caminho e continue pelas Routes 13, 14 e 15 até Fuchsia City.', 'Ao sul de Fuchsia, encontre Jessie e James na praia e receba os Gold Teeth, depois entregue-os ao guarda em sua casa para ensinar Strong Push ao seu parceiro.', 'Ao norte da cidade, procure o homem perto do Lapras, ao lado do GO Park, para ensinar Sea Skim ao seu parceiro.', 'Para entrar no ginásio de Koga, registre 50 espécies diferentes na Pokédex, depois derrote o líder para conquistar a Soul Badge.', 'Depois da vitória, volte a Lavender pelo mesmo caminho para seguir em direção a Saffron City.']), true), ARRAY['Saffron City'], to_jsonb(ARRAY['Entregue o Tea recebido de Brock a qualquer um dos guardas de Saffron City para liberar o acesso à cidade.', 'Ao norte de Saffron, visite o Fighting Dojo ao lado do ginásio e derrote os treinadores para escolher entre os Pokémon do tipo Lutador Hitmonlee e Hitmonchan.', 'Entre na Silph Co. e enfrente Blue, depois siga para o quinto andar e ajude seu rival a derrotar Archer e outro membro da Team Rocket para receber o Card Key.', 'No terceiro andar, use o teletransportador para avançar pela empresa e continue até enfrentar Jessie e James, depois siga até Giovanni.', 'Após derrotar Giovanni e receber a Master Ball, apresente um Pokémon de nível 45 ou superior na entrada do ginásio para enfrentar Sabrina.']), true), ARRAY['Victory Road'], to_jsonb(ARRAY['Na Route 22, enfrente seu rival e continue pela Route 23, passando pelos guardas que verificam suas insígnias até chegar à Victory Road.', 'Leve seu parceiro com as técnicas Sea Skim e Strong Push, depois use Strong Push dentro da Victory Road para empurrar as pedras sobre os interruptores e liberar as passagens.', 'Ao sair da Victory Road, siga até Indigo Plateau, onde você encontrará um Pokémon Center e uma loja para preparar sua equipe antes da Liga.']), true), ARRAY['Cerulean City'], to_jsonb(ARRAY['Atravesse a Route 3 e entre na caverna Mt. Moon, onde você encontrará treinadores e membros da Team Rocket.', 'Antes de sair da caverna, enfrente o Super Nerd e escolha entre o Dome Fossil e o Helix Fossil, que mais tarde poderão ser revividos como Pokémon dos tipos Água e Pedra.', 'Depois de escolher um dos fósseis no Mt. Moon, enfrente Jessie e James antes de continuar até a saída da caverna.', 'Ao sair da caverna, siga para a direita pela Route 4 até chegar a Cerulean City.', 'Ao chegar a Cerulean, converse com a garota na casa ao lado do Pokémon Center para receber um Bulbasaur após capturar 30 Pokémon.', 'Saia de Cerulean pelo norte, enfrente seu rival e os treinadores da ponte, depois siga para leste até encontrar a casa de Bill.', 'Depois de atravessar a ponte ao norte da cidade, converse com o treinador na Route 24 para receber um Charmander após capturar 50 Pokémon.', 'Converse com Bill, que está na forma de um Pokémon, e use o computador para ajudá-lo a voltar ao normal e receber o S.S. Ticket.', 'Para entrar no ginásio de Misty, apresente um Pokémon de nível 15 ou superior.', 'Volte a Cerulean City, derrote Misty para conquistar sua segunda insígnia e siga pela casa ao norte do ginásio, onde antes havia um policial.']), true), ARRAY['Viridian City'], to_jsonb(ARRAY['Depois de vencer Blaine, volte a Pallet Town e visite o laboratório do Professor Carvalho, onde Blue entregará a Key Stone e as Mega Stones dos iniciais de Kanto.', 'Siga para Viridian City e entre no ginásio para enfrentar Giovanni.', 'Após derrotá-lo e receber sua última insígnia, a Earth Badge, saia para oeste pela Route 22 em direção à Victory Road.']), true), ARRAY['Vermilion City'], to_jsonb(ARRAY['Passe pela casa roubada em Cerulean e siga ao sul pela Route 5, onde fica o Pokémon Day Care, depois entre na casa ao sudeste para atravessar a passagem subterrânea até a Route 6 e continuar para Vermilion City.', 'No porto ao sul da cidade, apresente o S.S. Ticket para embarcar na S.S. Anne, suba até encontrar seu rival e, depois de vencê-lo, ajude o capitão para que seu parceiro aprenda a técnica secreta Chop Down.', 'Ao deixar o navio, use Chop Down na árvore diante do ginásio para chegar a Lt. Surge.', 'Dentro do ginásio, encontre o primeiro interruptor nos cestos e procure o segundo em um cesto vizinho, depois derrote o líder Lt. Surge para receber sua terceira insígnia, a Thunder Badge.', 'Em Vermilion, converse com a policial no centro da cidade para receber um Squirtle após capturar 60 Pokémon.']), true), ARRAY['Cinnabar Island'], to_jsonb(ARRAY['Volte a Pallet Town e use Sea Skim ao sul pela Route 21 até chegar a Cinnabar Island.', 'Entre na Pokémon Mansion, ao norte da ilha, e acione os interruptores das estátuas para abrir as passagens até encontrar a Secret Key no porão.', 'Saia da mansão e use a Secret Key para abrir o ginásio de Blaine, líder do tipo Fogo, depois derrote-o para receber a Volcano Badge e volte a Pallet Town.']), true) WHERE slug IN ('pokemon-let-s-go-pikachu', 'pokemon-let-s-go-eevee');

COMMIT;

